(function(global){
'use strict';
const RA=global.RA=global.RA||{};
const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('troposphere','Troposphere combines Greek tropos, “turn or change,” with sphere; it names the lowest atmospheric layer, where weather occurs and where aircraft begin their climb.',[C('troposphere.s1','大气层','Most clouds form in the troposphere, where water vapour and changing weather are concentrated.','大多数云形成于对流层，那里水汽充足、天气变化频繁。','lower troposphere; weather in the troposphere','名词，指发生大多数天气现象的地球近地大气层。','cloud formation occurs in the lowest atmospheric layer.','大气层'),C('troposphere.s2','航空','Jets climb quickly through the troposphere after taking off from the airport.','喷气式飞机从机场起飞后迅速穿过对流层爬升。','rise through the troposphere; lower troposphere','名词，指飞机起飞和降落所处的近地大气区域。','the aircraft ascends through the air layer near the ground.','航空')],M('Most clouds form in the troposphere, the outer layer of space beyond the atmosphere.','Most clouds form in the troposphere, the lowest layer of the atmosphere.','troposphere是地球大气层的最低层，不是大气之外的外太空。','meaning'),[Q(1,'The troposphere is…','the lowest layer of Earth’s atmosphere','a layer above all weather and air','a type of trumpet','That is the meteorological sense.','meaning'),Q(2,'Jets climb through the troposphere after…','taking off from the airport','landing on the runway and stopping','entering a railway tunnel','The example describes the aircraft’s ascent from near the ground.','context'),Q(1,'Which phrase is natural?','clouds form in the troposphere','clouds form through tropospherically','troposphere clouds of form','In introduces the atmospheric layer where clouds form.','grammar'),Q(1,'Greek tropos meant…','turn or change','a faithful promise','a group of performers','The name alludes to changing atmospheric conditions.','word-formation')]);
P('tropospheric','Tropospheric is formed from troposphere with the adjective ending -ic; it means relating to the lowest atmospheric layer where weather occurs.',C('tropospheric.s1','大气科学','Tropospheric ozone forms near the ground when pollutants react in sunlight.','污染物在阳光下发生反应时，会在近地层形成对流层臭氧。','tropospheric ozone; tropospheric conditions','形容词，指与对流层及其中发生的过程有关的。','the ozone forms in the lower atmosphere.','大气科学'),M('Tropospheric ozone forms in the upper vacuum of space, far above Earth’s atmosphere.','Tropospheric ozone forms in the lower atmosphere near the ground.','tropospheric指对流层内的，不是大气层外太空中的。','meaning'),[Q(1,'Tropospheric ozone forms…','near the ground in the lower atmosphere','only on the surface of the Moon','inside a courtroom','The context identifies the atmospheric layer.','context'),Q(1,'Tropospheric means…','relating to the troposphere','relating to a trumpet','relating to a legal truce','That is the adjective’s meaning.','meaning'),Q(1,'Which phrase is natural?','tropospheric ozone','ozone tropospherically as noun','tropospheric of ozone','Tropospheric directly modifies the noun ozone.','grammar'),Q(1,'The suffix -ic forms…','an adjective meaning related to the base word','a person who performs an action','a plural noun','Tropospheric is the adjective form of troposphere.','word-formation')]);
P('trot','Trot came through Old French troter from Frankish *trotton, related to a Germanic verb meaning tread; it names a horse’s steady gait between walking and running.',C('trot.s1','马步','She trotted the pony around the ring at a steady pace between a walk and a canter.','她让小马以稳定的小跑步伐绕场，速度介于慢走与跑步之间。','at a trot; trot a horse around a ring','动词，指以小跑步伐前进或使马这样行进。','the pony moves faster than a walk but slower than a canter.','马步'),M('She trotted the pony around the ring at a slow walk and never let it move faster.','She trotted the pony around the ring at a steady, quicker-than-walking pace.','trot指比步行快、比跑步慢的步态，不是慢走。','meaning'),[Q(1,'A horse at a trot moves…','faster than a walk and slower than a canter','more slowly than a walk','only by flying','That is the gait described in the source.','meaning'),Q(1,'How did she move the pony?','Around the ring at a steady trot','Through a tunnel underground','Into a truce','The context names the route and gait.','context'),Q(1,'Which phrase is natural?','trot a pony around the ring','trot a pony into a walkly','pony trot arounded','Trot can take the animal as an object.','grammar'),Q(1,'The word came through Old French from a Germanic verb related to…','treading or stepping','writing a song','giving a speech','The older root described a step-like movement.','word-formation')]);
P('troubadour','Troubadour came through French from Old Provençal trobador, from trobar, “find or compose”; it named medieval southern French lyric poets, though the deeper origin is debated.',C('troubadour.s1','诗歌','The troubadour sang an Occitan love lyric at the medieval court.','这位游吟诗人在中世纪宫廷用奥克语唱了一首爱情抒情诗。','medieval troubadour; troubadour song/poetry','名词，指中世纪法国南部创作并演唱抒情诗的诗人，也可泛指游唱歌手。','the singer composes and performs verse.','诗歌'),M('The troubadour sang a medieval love lyric, but the sentence says the performer neither wrote nor sang verses.','The troubadour wrote and sang a medieval love lyric.','troubadour指创作或演唱抒情诗的歌者，原句否认这两种行为。','meaning'),[Q(1,'A medieval troubadour was…','a poet and singer of lyric verse','a farmer who grows tubers','a person who pulls a truck','That is the historical role.','meaning'),Q(1,'What language did the troubadour use in the example?','Occitan','Latin only','English sign language','The context states that the lyric is in Occitan.','context'),Q(1,'Which phrase is natural?','a troubadour sang a love lyric','a troubadour lyric sang by writingly','love a lyric troubadour to sang','A troubadour can sing a lyric as its subject.','grammar'),Q(1,'Old Provençal trobar meant…','to find or compose','to keep a promise','to dry with heat','The word’s history connects the poet with composing verse.','word-formation')]);
P('trouble','Trouble came through Old French trouble, with a deeper history linked to confusion or disturbance; it names problems or illness, and as a verb means worry or disturb.',[C('trouble.s1','困难/烦恼','We are in trouble because the ferry has left and the road is flooded.','渡轮已经离开、道路又被淹，我们现在遇到麻烦了。','be in trouble; cause/avoid trouble','名词，指困难、忧虑或需要额外努力处理的情况。','the travellers face two practical problems.','困难/烦恼'),C('trouble.s2','故障/疾病','The mechanic found trouble in the truck’s cooling system.','机械师发现卡车的冷却系统出了故障。','engine/heart trouble; have trouble with a machine','名词，指机器故障或疾病。','a component is not working properly.','故障/疾病'),C('trouble.s3','使烦恼','Does the noise from the trumpet trouble you while you study?','学习时，喇叭声会不会让你烦心？','trouble someone; be troubled by a noise','动词，指使某人担忧、烦恼或受到打扰。','the sound interrupts concentration.','使烦恼')],M('We are in trouble because the ferry left and the road flooded, so the journey has no problem at all.','We are in trouble because the ferry left and the road flooded, making the journey difficult.','in trouble表示遇到困难，与没有任何问题相矛盾。','meaning'),[Q(1,'The travellers are in trouble because…','they have lost the ferry and the road is flooded','the journey is perfectly easy','they reached their destination early','Sense 1 is a difficult situation.','context'),Q(2,'Trouble in a truck’s cooling system means…','a fault in the machine','a school subject','a musical instrument','Sense 2 can mean a mechanical fault.','meaning'),Q(3,'Does the noise trouble you? asks whether it…','worries or disturbs you','helps you sleep','is a piece of clothing','Sense 3 is the verb.','meaning'),Q(1,'Which phrase is natural?','have trouble with the engine','have a trouble of engine','trouble with have the engine','Trouble is usually uncountable in this construction.','grammar')]);
P('troublesome','Troublesome is formed from trouble plus -some, an adjective-forming ending; it describes something causing difficulty or extra work, or a naughty person hard to control.',[C('troublesome.s1','麻烦的','The mechanic traced a troublesome fault to a loose cable behind the dashboard.','机械师发现，令人头疼的故障源于仪表板后面一根松动的电缆。','troublesome problem/fault; troublesome to repair','形容词，指造成困难或额外工作的。','the fault takes effort to locate and fix.','麻烦的'),C('troublesome.s2','难管教','The troublesome boy kept interrupting the lesson and ignored the teacher’s instructions.','这个顽皮男孩不断打断课程，也不听老师的指示。','a troublesome child/boy; troublesome behaviour','形容词，指顽皮且难以管教的。','the child repeatedly disrupts the class.','难管教')],M('The troublesome fault was easy to diagnose and required no work at all.','The troublesome fault was difficult to locate and required extra repair work.','troublesome表示造成麻烦或额外工作，与毫不费力相反。','meaning'),[Q(1,'A troublesome fault is…','one that causes difficulty or extra work','one that repairs itself immediately','a harmless old custom','Sense 1 is about a problem.','meaning'),Q(2,'A troublesome boy may…','disrupt lessons and resist control','follow every instruction silently','teach a private tutorial','Sense 2 describes behaviour.','context'),Q(1,'Which phrase is natural?','a troublesome machine fault','a fault troublesomely machine','troublesome of machine fault','Troublesome modifies the noun phrase fault.','grammar'),Q(1,'The ending -some in troublesome forms…','an adjective meaning likely to cause or have something','a noun for a person','a past-tense verb','The suffix makes trouble into a descriptive adjective.','word-formation')]);
P('troubling','Troubling is formed from trouble with -ing; it describes information or events that make someone anxious because something seems wrong.',C('troubling.s1','令人担忧','The report contained several troubling omissions about the safety tests.','报告漏掉了几项安全测试信息，令人担忧。','troubling news/sign/omission; deeply troubling','形容词，指使人担心、觉得情况不对劲的。','missing safety information raises concern.','令人担忧'),M('The report’s troubling omissions reassured everyone that every safety test had been fully documented.','The report’s omissions were troubling because key safety tests were not documented.','troubling表示引发担忧，遗漏关键安全测试不会使人安心。','meaning'),[Q(1,'Troubling omissions are…','missing details that make people anxious','complete records that reassure everyone','a kind of instrument','That is the adjective’s meaning.','meaning'),Q(1,'Why were the report’s omissions troubling?','Safety tests were missing','The report was too short to read','A trout was in the river','The example links omissions to safety concerns.','context'),Q(1,'Which phrase is natural?','a troubling sign','a troublingly sign','a sign trouble to','Troubling is an adjective modifying sign.','grammar'),Q(1,'Troubling is formed from…','trouble plus the participial ending -ing','trough plus -ful','truly plus -ness','The -ing form functions as an adjective here.','word-formation')]);
P('trough','Trough comes from Old English trog, a long vessel; by analogy with its low curved shape, it also names a low point in a cycle or mood.',[C('trough.s1','食槽','The pigs crowded around the trough while the farmer poured in fresh feed.','农夫倒入新饲料时，猪群挤在食槽周围。','water/feed trough; fill a trough','名词，指供动物盛放食物或水的长形开口容器。','the container holds feed for the pigs.','食槽'),C('trough.s2','低谷','After a long recession, the economy reached a trough and began to recover.','经历长期衰退后，经济触底并开始复苏。','economic trough; hit/reach a trough','名词，比喻活动、经济或情绪周期中的低点。','the economy stops falling at its lowest point.','低谷')],M('The farmer poured feed into the trough, a small instrument used to play music.','The farmer poured feed into the trough, the long container used to hold animal food.','trough指动物食槽，不是乐器。','meaning'),[Q(1,'A farm trough is…','a long open container for animal food or water','a narrow railway track','a formal pause in fighting','Sense 1 is the container.','meaning'),Q(2,'An economic trough is…','the low point of a cycle','the moment of fastest growth','a kind of storm','Sense 2 is figurative.','context'),Q(1,'Which phrase is natural?','fill the trough with water','fill with troughing water','trough fill water at','With introduces what is put in the container.','grammar'),Q(1,'The word trough came from Old English for…','a long container','a travelling singer','a strong wind','The economic use developed by comparison with a low-shaped vessel.','word-formation')]);
P('troupe','Troupe came from French troupe, “company or group,” and names performers travelling together; it can also refer to any group acting or moving together, or serve as a verb for touring as performers.',[C('troupe.s1','演出团体','The dance troupe is touring the country with a new production.','舞蹈团正带着新作品在全国巡演。','dance/acting troupe; a troupe of performers','名词，指共同演出的演员、舞者或歌手团体。','the performers work together in one production.','演出团体'),C('troupe.s2','一群人','The whole troupe headed for the beach after the final rehearsal.','最后一次排练结束后，整群人去了海滩。','a troupe of visitors/children; the whole troupe','名词，泛指一起行动或移动的一群人。','the group moves together.','一群人'),C('troupe.s3','巡演','The company trouped through small southern towns during the summer.','夏天，这个演出团巡回走过南方的小城镇。','troupe through towns; troupe around the region','动词，指作为演出团体巡回演出。','the company travels from town to town performing.','巡演')],M('The dance troupe toured the country, although the group had no performers and gave no production.','The dance troupe toured the country with its performers and new production.','troupe指共同演出的团体，原句否认团体由表演者组成。','meaning'),[Q(1,'A dance troupe is…','a group of performers who work together','a single audience member','a long container for animal feed','Sense 1 is the performing group.','meaning'),Q(2,'The whole troupe headed for the beach means…','the whole group went together','only one dancer stayed behind','the theatre was closed','Sense 2 refers broadly to a group.','context'),Q(3,'The company trouped through towns means it…','travelled around performing','built a trough','lost its legal trust','Sense 3 is the verb.','meaning'),Q(1,'Which phrase is natural?','a troupe of dancers','a troupe dancers ofly','dancers troupe at a','Of introduces the performers in the group.','grammar')]);
P('trousers','Trousers entered English from Gaelic/Middle Irish triubhas, “close-fitting shorts”; the plural form suits a garment with two separate leg sections.',C('trousers.s1','衣物','These trousers are too long, so I will have the hems shortened.','这条裤子太长了，所以我要把裤脚改短。','a pair of trousers; wear trousers','名词复数，指从腰部向下、分别覆盖两条腿的衣物。','the garment has two leg sections.','衣物'),M('These trousers are too long, so I will shorten the sleeves at the cuffs.','These trousers are too long, so I will shorten the legs at the hems.','trousers是裤子，应改短裤腿和裤脚，不是袖子。','meaning'),[Q(1,'Trousers cover…','the lower body with a separate part for each leg','the head from the sun','the hands while drying','That is the clothing definition.','meaning'),Q(1,'Why will the speaker alter the trousers?','They are too long','They are too short to wear','They are wet from a storm','The sentence states the reason.','context'),Q(1,'Which expression is correct?','a pair of trousers','a trouser','two trouser','Trousers is plural in form, so pair of is common.','grammar'),Q(1,'The older Gaelic source triubhas meant…','close-fitting shorts','a vessel for animal feed','a pause in fighting','The English garment name came through a Celtic word.','word-formation')]);
P('trout','Trout came through Old English and Old French from Late Latin tructa, perhaps from Greek trōktēs, “nibbler”; it names freshwater fish and, in dated joking use, an old person.',[C('trout.s1','鱼类','They caught two trout in the upper river and released the smaller one.','他们在上游捕到两条鳟鱼，并放生了较小的一条。','freshwater trout; catch/release trout','名词，指常见于淡水、皮肤有斑点并供食用或垂钓的鱼。','the fish are caught in a freshwater river.','鱼类'),C('trout.s2','旧式戏称','In the old comedy, the grumpy neighbour is jokingly called an old trout by his friends.','在那部老喜剧里，脾气暴躁的邻居被朋友戏称为“老家伙”。','old trout (dated, informal, teasing)','名词，旧式、略带揶揄地称呼一位老人。','the phrase is a teasing label in a comedy.','旧式戏称')],M('They caught two trout in the river, both of which were desert birds with feathers.','They caught two trout in the river, both freshwater fish.','trout是鱼类，不是鸟类。','meaning'),[Q(1,'A trout is…','a freshwater fish','a bird that sings love lyrics','a type of trouser','Sense 1 is the animal meaning.','meaning'),Q(2,'“Old trout” in the old comedy is…','a dated, teasing way to refer to an older person','a modern formal title of respect','a freshwater fish in a river','Sense 2 is informal and somewhat mocking.','context'),Q(1,'Which phrase is natural?','catch trout in a river','catch a trouting riverly','trout catch to river at','Catch trout is the natural verb-object phrase.','collocation'),Q(1,'Late Latin tructa may come from Greek for…','a kind of fish literally called a nibbler','a long garment with two legs','a promise of peace','The proposed Greek source is related to nibbling.','word-formation')]);
P('trove','Trove is shortened from the fixed phrase treasure trove; it names a valuable store or collection of objects, information, or discoveries.',C('trove.s1','宝藏/资料库','The attic was a trove of letters and photographs from the 1940s.','阁楼里收藏着大量20世纪40年代的信件和照片。','a trove of information/letters; treasure trove','名词，指有价值的物品、信息或发现的丰富集合。','many interesting historical items are collected there.','宝藏/资料库'),M('The archive was a trove of letters, but it contained no documents, photographs, or information.','The archive was a trove of letters, photographs, and historical information.','trove指丰富的收藏，原句却说其中什么资料也没有。','meaning'),[Q(1,'A trove of letters is…','a valuable collection of letters','one empty envelope','a group of performers','That is the noun meaning.','meaning'),Q(1,'What was found in the attic?','Letters and photographs from the 1940s','A medical tumor','A trumpet and a trough','The context gives the collection’s contents.','context'),Q(1,'Which phrase is natural?','a trove of information','a trove informationly','information to a trove of','Of introduces what the collection contains.','grammar'),Q(1,'Trove is commonly shortened from…','treasure trove','touring troupe','troubled truth','The established compound phrase is treasure trove.','word-formation')]);
P('truant','Truant came through Old French truant, whose deeper origin is uncertain; as a verb, play truant means stay away from school without permission, and as a noun it names such a pupil.',[C('truant.s1','逃学','He was caught playing truant behind the sports hall instead of attending class.','他没有去上课，而是在体育馆后面逃学时被抓到。','play truant; a school truant','动词短语/名词，指未经允许旷课或旷课的学生。','the pupil deliberately misses school.','逃学')],M('He was playing truant, which means he attended every class with written permission.','He was playing truant, which means he stayed away from school without permission.','play truant指未经允许逃学，原句描述的是正常出勤。','meaning'),[Q(1,'Playing truant means…','staying away from school without permission','attending every lesson','performing in a troupe','That is the school-attendance sense.','meaning'),Q(1,'Where was he caught?','Behind the sports hall','In the classroom taking a test','At a hospital','The context gives his location.','context'),Q(1,'Which phrase is standard?','play truant','play a truanting','truant play at','Play truant is the established expression.','grammar'),Q(1,'The deeper origin of truant is…','uncertain beyond its route through Old French','certainly a Latin word for fish','certainly Greek for sphere','The source is obscure, so a more specific root should not be asserted.','word-formation')]);
P('truce','Truce is related to Old English treow, “faith, pledge, or agreement”; it names a mutually agreed pause in fighting or the period during which hostilities stop.',[C('truce.s1','停战','The two armies agreed to a truce for the holiday so civilians could cross the border.','两支军队同意节日期间停战，让平民能够越过边境。','agree to/call a truce; temporary truce','名词，指冲突各方共同同意的临时停战。','the commanders mutually pause the fighting.','停战'),C('truce.s2','停战期间','Life slowly returned to the town during the truce.','停战期间，镇上的生活慢慢恢复了。','during/under a truce; break the truce','名词，指战争或争吵暂停的一段时间。','the quiet interval allows daily life to resume.','停战期间')],M('The armies agreed to a truce and continued attacking each other throughout the pause.','The armies agreed to a truce and stopped fighting temporarily.','truce是暂时停止敌对行动，持续攻击与停战相矛盾。','meaning'),[Q(1,'A truce between armies is…','a mutually agreed temporary pause in fighting','a permanent victory by one side','a storm at sea','Sense 1 is the agreement.','meaning'),Q(2,'During the truce, life…','slowly returned to normal','became more violent every minute','was mapped topographically','Sense 2 names the period of pause.','context'),Q(1,'Which phrase is natural?','agree to a truce','agree a truce ofly','truce agree at for','To follows agree in this construction.','grammar'),Q(1,'Old English treow was associated with…','faith, pledge, or agreement','a musical instrument','a low container','The historical root connects a truce with a pledge.','word-formation')]);
P('truck','Truck’s vehicle noun has an uncertain history, while the verb was influenced by truck meaning transport; it means a goods vehicle or to carry goods by truck.',[C('truck.s1','卡车','The truck was loaded with wood before it left for the construction site.','卡车装好木材后驶往建筑工地。','delivery/freight truck; load a truck','名词，指用于运送货物的大型机动车。','the vehicle carries timber to a work site.','卡车'),C('truck.s2','用卡车运输','The fruit is trucked to the city before the morning markets open.','水果在早市开门前用卡车运进城。','truck goods to a city; truck produce','动词，指用卡车运送货物。','the produce is carried by road in a truck.','用卡车运输')],M('The truck carried the wood, but the vehicle was a small paper towel used to wipe a spill.','The truck carried the wood in a large motor vehicle to the construction site.','truck在此指运货大型机动车，不是纸巾。','meaning'),[Q(1,'A truck is…','a large motor vehicle for carrying goods','a small hand towel','a kind of flower','Sense 1 is the vehicle meaning.','meaning'),Q(2,'Fruit is trucked to the city means it is…','transported there by truck','left to grow in a tub','towed by a horse','Sense 2 is the verb.','context'),Q(1,'Which phrase is natural?','load a truck with wood','load wood in a truckingly','truck load to wood the','With introduces what the truck carries.','grammar'),Q(1,'The history of truck as a vehicle is…','uncertain','certainly from Greek for fish','certainly from Old English for faith','The etymology is not settled, so avoid inventing a precise root.','word-formation')]);
P('trudge','Trudge is an English verb of uncertain origin; it means walk slowly with heavy steps, usually because one is tired or the ground is difficult.',[C('trudge.s1','艰难行走','They trudged back through the snow after the bus broke down.','公交车抛锚后，他们深一脚浅一脚地穿过雪地往回走。','trudge through snow/mud; trudge home','动词，指因疲倦或路况困难而沉重缓慢地走。','their steps are slow and effortful in deep snow.','艰难行走'),C('trudge.s2','艰难的步行','It was a two-hour trudge to the station with the heavy suitcases.','拖着沉重行李走到车站，足足花了两小时。','a long/tiring trudge; a trudge through mud','名词，指长距离、费力而缓慢的步行。','the journey on foot takes considerable effort.','艰难的步行')],M('They trudged through deep snow at a sprint, moving quickly and effortlessly.','They trudged through deep snow with slow, heavy, tiring steps.','trudge表示沉重缓慢地走，与轻松冲刺相反。','meaning'),[Q(1,'To trudge through snow is to…','walk slowly with heavy effort','run lightly at full speed','drive a truck','Sense 1 is the verb.','meaning'),Q(2,'A two-hour trudge is…','a long tiring walk','a fast aircraft landing','a short trumpet solo','Sense 2 is the noun.','context'),Q(1,'Which phrase is natural?','trudge home through the snow','trudge home by sprinting quickly','snow trudge to homeing','Through introduces the difficult surface crossed.','collocation'),Q(1,'The deeper origin of trudge is…','uncertain','definitely Latin for whole','definitely Greek for name','The source is obscure, so no precise root is asserted.','word-formation')]);
P('true','True comes from Old English triewe/treowe, “faithful or trustworthy,” from a Germanic root meaning firm; it later developed the factual sense “not false.”',[C('true.s1','真实','The story is true: the ferry really left before the road flooded.','这个故事是真的：渡轮确实在道路被淹前离开了。','true story/fact; come true','形容词，指符合事实或现实、并非虚假的。','the events actually happened.','真实'),C('true.s2','守信','She is true to her word and always returns borrowed books on time.','她说话算数，总会按时归还借来的书。','true to one’s word; a true friend','形容词，指忠诚、守信或真正可靠的。','she consistently keeps her promise.','守信')],M('The story is true, meaning every event in it was invented and never happened.','The story is true, meaning its events really happened.','true在此表示符合事实，不是虚构。','meaning'),[Q(1,'A true story is…','one based on events that really happened','a story invented from nothing','a story written in a textbook style','Sense 1 concerns facts.','meaning'),Q(2,'She is true to her word means she…','keeps her promises','changes every promise','writes a troubadour song','Sense 2 concerns loyalty and reliability.','context'),Q(1,'Which phrase is natural?','true to her word','true for her wordly','truth to her wordly','True to one’s word is the standard expression.','collocation'),Q(1,'Old English triewe was associated with…','faithfulness and trustworthiness','a violent sea wave','a low point in a cycle','The older sense was faithful or trustworthy.','word-formation')]);
P('truly','Truly is formed from true plus -ly; it means genuinely or exactly, and can also express sincerity in thanks or a letter closing.',[C('truly.s1','确实','I truly believe he meant no harm when he missed the meeting.','我确实相信他错过会议并非有意为之。','truly believe/know; truly remarkable','副词，指真实地、确实地，不夸大其词。','the speaker states sincere conviction.','确实'),C('truly.s2','真诚','At the end of the formal letter, she wrote Yours truly before signing her name.','在正式信件末尾，她写下“谨上”并署上自己的姓名。','thank you truly; yours truly','副词，表示真诚地，尤其用于感谢或信件结尾。','the conventional closing appears before the writers signature.','真诚')],M('I truly believe he meant no harm means I am pretending to believe it and actually doubt him.','I truly believe he meant no harm means I sincerely believe he had no bad intention.','truly表示真诚、确实，不是表面假装。','meaning'),[Q(1,'I truly believe means…','I sincerely believe it','I am only pretending to believe it','I am describing a railway route','Sense 1 is genuine conviction.','meaning'),Q(2,'Yours truly at the end of a letter is…','a polite sign-off before the writers signature','an informal greeting at the start of a letter','a promise that a letter will arrive tomorrow','Sense 2 is a sincere closing formula in a letter.','context'),Q(1,'Which phrase is natural?','I truly appreciate your help.','I truly appreciation your help.','I appreciate trulyly your helpingly.','Truly modifies the verb appreciate.','grammar'),Q(1,'Truly is formed from…','true plus -ly','truce plus -s','trunk plus -er','The suffix creates an adverb.','word-formation')]);
P('trumpet','Trumpet came through French trompette from Italian trombetta, a diminutive of tromba; it names a brass instrument and means announce or praise something loudly.',[C('trumpet.s1','乐器','He plays the trumpet in the school band and practises every afternoon.','他在学校乐队吹小号，每天下午练习。','play/blow a trumpet; trumpet solo','名词，指通过吹奏发声的铜管乐器。','the musician blows air to produce notes.','乐器'),C('trumpet.s2','大肆宣扬','The company trumpeted its success before independent auditors checked the figures.','独立审计师核实数据前，公司就大肆宣扬自己的成功。','trumpet a success/achievement; trumpet something loudly','动词，比喻大声、自豪地宣传某事。','the company promotes its achievement noisily.','大肆宣扬')],M('He played the trumpet by striking the brass instrument with a drumstick and never blowing into it.','He played the trumpet by blowing into its mouthpiece.','trumpet是吹奏的铜管乐器，不是用鼓槌敲击。','meaning'),[Q(1,'A trumpet is…','a brass instrument played by blowing','a woodwind instrument played with keys only','a container for animal feed','Sense 1 is the instrument.','meaning'),Q(2,'The company trumpeted its success means it…','praised or announced it loudly','hid it from the public','tested it in a laboratory','Sense 2 is the verb.','context'),Q(1,'Which phrase is natural?','play the trumpet','play at the trumpetly','trumpet playing to','Play is the normal verb for a musical instrument.','collocation'),Q(1,'Italian trombetta is a diminutive of…','tromba','tundra','truce','The French and Italian forms lie behind the English word.','word-formation')]);
P('trumpeter','Trumpeter is formed from trumpet plus the agent suffix -er; it names a person who plays the instrument in a band, orchestra, or military unit.',C('trumpeter.s1','演奏者','The trumpeter opened the ceremony with a bright fanfare from the balcony.','小号手在阳台上吹奏嘹亮的号角曲，为仪式开场。','jazz/military trumpeter; solo trumpeter','名词，指演奏小号的人。','the musician performs on the trumpet.','演奏者'),M('The trumpeter opened the ceremony by playing a flute and never touching a trumpet.','The trumpeter opened the ceremony by playing a trumpet fanfare.','trumpeter指小号演奏者，不是长笛演奏者。','meaning'),[Q(1,'A trumpeter is…','someone who plays the trumpet','someone who plays only a flute','someone who studies the tundra','That is the agent-noun meaning.','meaning'),Q(1,'What did the trumpeter play at the ceremony?','A fanfare','A tuber','A truce','The context names a trumpet fanfare.','context'),Q(1,'Which phrase is natural?','a jazz trumpeter','a trumpetly jazz person','trumpeter of jazzing','Jazz modifies the type of trumpet player.','grammar'),Q(1,'The suffix -er in trumpeter marks…','a person who performs the action','a state of being true','a place where aircraft land','It forms the performer noun from trumpet.','word-formation')]);
P('trunk','Trunk came through Anglo-French and Old French forms from Medieval Latin truncus, “tree stem or main body”; the Latin word’s deeper origin is uncertain. English uses trunk for a tree’s main stem, an elephant’s long nose, a strong chest, or a car’s rear storage compartment.',[C('trunk.s1','树干','A woodpecker tapped on the trunk of the old oak while the branches moved in the wind.','树枝随风摇动时，一只啄木鸟在老橡树的树干上啄击。','tree trunk; climb the trunk','名词，指树木粗壮的主干。','the woodpecker taps the central woody stem.','树干'),C('trunk.s2','箱子/象鼻/后备箱','We put the suitcases in the trunk before driving to the hotel.','开车去酒店前，我们把行李箱放进了汽车后备箱。','car trunk; elephant trunk; travel trunk','名词，可指汽车后备箱、旅行箱或大象的长鼻。','the luggage goes into the rear storage compartment.','后备箱')],M('We put the suitcases in the trunk, which was the cars front passenger seat.','We put the suitcases in the trunk, the storage space at the back of the car.','此处 trunk 是汽车后备箱，不是前排座位。','meaning'),[Q(1,'In the first sense, a trunk is…','the main woody stem of a tree','a small flower bulb','a boat that tows ships','Sense 1 names the central stem.','meaning'),Q(2,'Where did the travellers put the suitcases?','In the cars rear storage compartment','Inside the oak tree','On the subway train','The context uses trunk as a car storage space.','context'),Q(1,'Which phrase is natural?','the trunk of an oak','the oak trunkly of','an oak trunks of','Of links the tree and its main stem.','grammar'),Q(1,'Latin truncus referred to a…','stem or main body','day named for a god','Japanese harbor wave','The English word came through French from Latin.','word-formation')]);
P('trust','Trust comes from Old Norse traust, “help, confidence, or protection”; it means belief in someone reliable, the act of relying on them, or a legal arrangement holding property for another.',[C('trust.s1','信任','Trust is essential when a team shares responsibility for a difficult rescue.','团队共同承担艰巨救援任务时，信任至关重要。','mutual trust; earn/build trust','名词，指相信某人诚实、可靠的信心。','team members rely on each other.','信任'),C('trust.s2','相信/托付','I trust Maya to lock the laboratory after the evening shift.','我相信玛雅会在晚班后锁好实验室。','trust someone to do something; trust in','动词，指相信某人可靠，或把责任交给对方。','the speaker relies on Maya to complete the task.','相信/托付'),C('trust.s3','信托','The family placed the house in trust for the youngest child.','这家人把房屋设立信托，为最小的孩子持有。','hold/place property in trust; a charitable trust','名词，指为受益人持有和管理财产的法律安排。','the property is managed for another person.','信托')],M('I trust Maya to lock the laboratory, so I am certain she will leave it open and insecure.','I trust Maya to lock the laboratory, so I rely on her to secure it.','trust someone to do something表示相信对方会履责，不能接与信任相反的预期。','meaning'),[Q(1,'Mutual trust in a team is…','confidence that members are reliable','a legal document for selling food','a sudden hard pull on a rope','Sense 1 concerns confidence between people.','meaning'),Q(2,'I trust Maya to lock up means…','I rely on her to do it','I suspect she will refuse','I am storing property for her','Sense 2 is the verb construction.','context'),Q(3,'A house held in trust is…','managed for a beneficiary under a legal arrangement','a building that cannot be entered','a vehicle storage compartment','Sense 3 is the legal use.','meaning'),Q(2,'Which pattern is correct?','trust someone to do something','trust someone doing to something','trust to someone do something','Trust can take an object followed by an infinitive.','grammar')]);
P('trustworthy','Trustworthy is formed from trust plus worthy, “deserving”; it describes a person or source that can be relied on to be honest and dependable.',C('trustworthy.s1','可靠诚信','The editor chose a trustworthy translator who checked every quotation against the original.','编辑选择了一位可靠的译者，他把每条引文都与原文核对。','trustworthy source/person; prove trustworthy','形容词，指值得信赖、诚实可靠的。','the translator carefully verifies the material.','可靠诚信'),M('A trustworthy witness deliberately changed the dates and hid the original records.','A trustworthy witness gave accurate dates and preserved the original records.','故意改日期并藏起记录是失信行为，与trustworthy相反。','meaning'),[Q(1,'A trustworthy witness is…','reliable and honest','likely to falsify records','a vessel used for juice','That is the adjective meaning.','meaning'),Q(1,'Why was the translator trustworthy?','The editor relied on careful checking','The translator removed all quotations','The editor did not know the translator','The example gives evidence for reliability.','context'),Q(1,'Which phrase is natural?','a trustworthy source','a trustworthiness source','a source trustworthyly','Trustworthy directly modifies source.','grammar'),Q(1,'The ending -worthy means…','deserving of or fit for something','the past tense of a verb','a small swollen plant stem','Worthy contributes the sense “deserving trust.”','word-formation')]);
P('truth','Truth comes from Old English triewth or treowth, related to true; it means actual facts, and can also name a principle accepted as universally valid.',[C('truth.s1','事实','The witness told the truth about the time the ferry left the harbour.','证人如实说明了渡轮离港的时间。','tell/speak the truth; the truth about','名词，指事情的真实情况或事实。','the witness reports what actually happened.','事实'),C('truth.s2','普遍真理','The mathematician described the result as a truth that holds for every whole number.','数学家把这个结果称为对每个整数都成立的真理。','a universal/fundamental truth; a truth about life','名词，指被普遍接受或被认为普遍成立的事实或观念。','the rule applies across the whole stated class.','普遍真理')],M('The witness told the truth, although every detail of the account was deliberately invented.','The witness told the truth, giving an account that matches what happened.','truth是符合事实的内容，不是故意编造的说法。','meaning'),[Q(1,'Tell the truth means…','say what really happened','invent an account knowingly','keep a house for a child','Sense 1 concerns actual facts.','meaning'),Q(2,'A universal truth is presented as…','an idea or fact applying generally','a private guess with no wider validity','a weekday after Monday','Sense 2 concerns general validity.','context'),Q(1,'Which phrase is standard?','the truth about the delay','a truth about the delayly','the truth of about the delay','About introduces the subject of the facts.','grammar'),Q(1,'Old English triewth is related to…','true','tuberculosis','trumpet','Truth developed from the same word family as true.','word-formation')]);
P('truthful','Truthful is formed from truth plus -ful, meaning “full of”; it describes a person willing to tell the truth or a representation that accurately reflects events.',[C('truthful.s1','诚实的','Please give me a truthful account of what happened in the workshop.','请如实告诉我车间里发生了什么。','truthful answer/account; be truthful','形容词，指愿意说真话、不隐瞒事实的。','the speaker asks for an honest account.','诚实的'),C('truthful.s2','真实准确的','The documentary offers a truthful picture of daily life in the village.','这部纪录片真实地呈现了村里的日常生活。','truthful picture/representation; a truthful description','形容词，指准确反映真实情况的。','the film represents ordinary life accurately.','真实准确的')],M('The witness was truthful, inventing a different story each time she was questioned.','The witness was truthful, giving the same accurate account each time.','反复编造不同说法不符合truthful所表达的诚实。','meaning'),[Q(1,'A truthful answer is…','honest and not hiding what happened','deliberately false','a container for ice cream','Sense 1 is about honesty.','meaning'),Q(2,'A truthful picture of village life…','represents it accurately','shows only imaginary events','is a legal trust','Sense 2 concerns accurate representation.','context'),Q(1,'Which phrase is natural?','a truthful account','a truthfully account','a truthfulness account','Truthful is the adjective modifying account.','grammar'),Q(1,'The suffix -ful in truthful contributes…','full of or characterized by','the meaning of a place','the past tense','Truthful means characterized by truth.','word-formation')]);
P('try','Try came through Old French trier, “pick out or sift,” though the deeper history is uncertain; it means make an effort, test something, examine a case in court, or an attempt.',[C('try.s1','努力尝试','Try to reach the station before the last train leaves.','尽量在末班车离开前赶到车站。','try to do; try hard; give it a try','动词，指努力去做某事。','the speaker urges an effort to arrive in time.','努力尝试'),C('try.s2','试用/测试','The technician tried a different cable to see whether the monitor would work.','技术员换了一根电缆，看看显示器能否工作。','try a method/product; try doing','动词，指试用或测试某物、做法以判断效果。','the cable is tested to diagnose the fault.','试用/测试'),C('try.s3','审理','A jury will try the case next month after hearing both sides.','陪审团将在听取双方意见后于下月审理此案。','try a case/defendant; be tried for','动词，指在法庭上审理案件或被告。','the court examines the case.','审理'),C('try.s4','尝试','Have a try at the puzzle before I show you the answer.','我告诉你答案前，先试着做一下这道谜题。','have/give something a try; a first try','名词，指一次尝试或努力。','the listener is invited to attempt the puzzle.','尝试')],M('The technician tried a new cable, but she refused to test it and left the fault unexplored.','The technician tried a new cable to test whether it fixed the fault.','此处try是实际测试，不是拒绝测试。','meaning'),[Q(1,'Try to reach the station means…','make an effort to get there','examine a defendant in court','store property for a child','Sense 1 is an effort.','meaning'),Q(2,'The technician tried a cable to…','test whether it solved the problem','avoid checking the monitor','tell a universal truth','Sense 2 is a test.','context'),Q(3,'A jury will try the case means it will…','hear and examine it in court','repair a truck','take the Tube','Sense 3 is the legal verb.','meaning'),Q(4,'Have a try at the puzzle uses try as…','a noun meaning an attempt','an adjective meaning reliable','a legal arrangement','Sense 4 is a countable attempt.','grammar')]);
P('try out','Try out combines try with out and means test something in use, or take part in an audition or selection test for a team or role.',[C('try out.s1','试用','The shop lets cyclists try out the new helmet before buying it.','商店允许骑行者在购买前试戴这款新头盔。','try out a product/method; try it out','动词短语，指试用某物以判断效果或是否合适。','the helmet is tested before a decision to buy.','试用'),C('try out.s2','选拔试演','Several students will try out for the school musical on Friday.','几名学生将在周五参加学校音乐剧的选拔试演。','try out for a team/role; tryouts for','动词短语，指参加选拔以争取加入团队或获得角色。','the students perform to compete for parts.','选拔试演')],M('The cyclist tried out the helmet without wearing it or checking whether it fit.','The cyclist tried out the helmet by wearing it and checking the fit.','try out是实际试用，不能在未使用时说已测试。','meaning'),[Q(1,'Try out a helmet means…','use it to judge how well it works','store it for someone else','announce it loudly','Sense 1 is product testing.','meaning'),Q(2,'Students try out for the musical to…','audition for a role','buy a helmet','test a cable at the shop','Sense 2 is selection by audition.','context'),Q(1,'Which sentence uses the phrase correctly?','She tried out the new bicycle before buying it.','She tried the bicycle out for a role in the play.','She try outed the bicycle tomorrow.','Try out can describe testing a product.','grammar'),Q(2,'In try out for a role, out belongs to…','the phrasal verb meaning audition','the noun musical','the past tense suffix','The complete phrasal verb means participate in a selection test.','word-formation')]);
P('trying','Trying is the -ing form of try used as an adjective; it describes an experience that is annoying or stressful because difficulties continue.',C('trying.s1','令人难受的','Caring for two sick children alone was a trying week for their father.','独自照顾两个生病的孩子，对他们的父亲来说是艰难的一周。','a trying time/day; find something trying','形容词，指因困难持续而令人烦恼或承受压力的。','the continuing care demands are stressful.','令人难受的'),M('The trying week was effortless and relaxing from beginning to end.','The trying week was stressful because the care demands continued.','trying描述令人烦恼或有压力的经历，与轻松惬意相反。','meaning'),[Q(1,'A trying week is…','stressful or difficult to endure','completely effortless','a week of court hearings only','That is the adjective meaning.','meaning'),Q(1,'Why was the week trying for the father?','He cared for two sick children alone','He had no responsibilities','He bought a new helmet','The context explains the ongoing strain.','context'),Q(1,'Which phrase is natural?','a trying experience','a tried experience meaning stressful','a tryingly experience','Trying is the adjective modifying experience.','grammar'),Q(1,'Here trying is formed from…','try plus -ing and used as an adjective','truce plus -ly','tub plus -er','The participial form functions adjectivally.','word-formation')]);
P('tsunami','Tsunami is borrowed from Japanese 津波, “harbor wave,” formed from tsu, “harbor,” and nami, “wave”; it is a series of large waves caused by sudden displacement of seawater.',C('tsunami.s1','海啸','The tsunami reached the coastal village less than an hour after the offshore earthquake.','海底地震发生不到一小时，海啸便抵达沿海村庄。','tsunami warning; tsunami wave; trigger a tsunami','名词，指通常由地震等引发的一系列巨大海浪。','the earthquake displaces seawater and the wave train reaches shore.','海啸'),M('The tsunami arrived as one small ripple caused by a passing fish.','The tsunami arrived as a series of huge waves generated by the earthquake.','海啸是大规模海浪，不是鱼引起的小涟漪。','meaning'),[Q(1,'A tsunami is…','a series of very large sea waves','a gentle daily tide only','a swollen plant stem','That is the geological event described.','meaning'),Q(1,'What triggered the example tsunami?','An offshore earthquake','A trumpet performance','A court case','The sentence names the cause.','context'),Q(1,'Which phrase is natural?','a tsunami warning','a tsunamiing warning','a warning to tsunami at','Tsunami is used as a noun modifier.','grammar'),Q(1,'Japanese tsu means…','harbor','wave','earthquake','The compound combines harbor and wave.','word-formation')]);
P('tub','Tub is recorded from Middle Dutch tubbe, “tub or vat”; it names a wide open container and, in another common sense, a bathtub.',[C('tub.s1','容器','She carried a tub of ice cream to the picnic table and set out spoons.','她把一桶冰淇淋拿到野餐桌旁，并摆好勺子。','a tub of ice cream; plastic tub','名词，指宽而敞口的容器。','the container holds a quantity of ice cream.','容器'),C('tub.s2','浴缸','The children splashed happily in the tub while their mother prepared towels.','母亲准备毛巾时，孩子们在浴缸里开心地戏水。','bath tub; get in/out of the tub','名词，口语中指浴缸。','the children are bathing in the household fixture.','浴缸')],M('She carried a tub of ice cream, but the tub was a narrow sealed pipe that could hold no food.','She carried a wide open tub of ice cream to the picnic.','此处 tub 是盛放冰淇淋的敞口容器，不是密封管道。','meaning'),[Q(1,'A tub of ice cream is…','a wide open container holding ice cream','a small boat pulling a ship','a court hearing','Sense 1 is a container.','meaning'),Q(2,'The children splashed in the tub means they were…','bathing in the bathtub','walking through a harbor wave','playing a brass instrument','Sense 2 is the bath fixture.','context'),Q(1,'Which phrase is natural?','a tub of ice cream','a tub ice creamly','an ice cream tub ofly','Of introduces the contents.','grammar'),Q(1,'The older Dutch source tubbe meant…','a tub or vat','a sea wave','a weekday','That is the source sense.','word-formation')]);
P('tube','Tube came through French from Latin tubus, “pipe”; it names a hollow cylinder, and, capitalized in British use, the London Underground railway system.',[C('tube.s1','管状物','The paint comes in a metal tube with a screw cap at one end.','颜料装在一支金属管里，一端有旋盖。','a tube of paint; metal/plastic tube','名词，指用来输送或盛装物质的中空长圆筒。','the hollow container holds paint.','管状物'),C('tube.s2','伦敦地铁','We took the Tube from the hotel to the museum during the rain.','下雨时，我们从酒店乘伦敦地铁去了博物馆。','take/use the Tube; Tube station/line','专有名词，英国尤指伦敦的地下铁路系统。','the travellers ride the city underground railway.','伦敦地铁')],M('The paint came in a tube, a solid block with no hollow space inside.','The paint came in a hollow tube with a cap.','tube是中空的圆筒状物，实心块不符合其含义。','meaning'),[Q(1,'A tube of paint is…','paint held in a long hollow container','paint poured into a flat tray only','a train ticket','Sense 1 is the container.','meaning'),Q(2,'Taking the Tube in London means…','riding the underground railway','walking through a tree trunk','going to a court trial','Sense 2 is the transit system.','context'),Q(1,'Which sentence is correct?','She squeezed paint from the tube.','She squeezed a tube paint from.','She squeezed from paint the tubely.','From introduces the source container.','grammar'),Q(1,'Latin tubus meant…','pipe','trust','weekday','The word entered English through French from Latin.','word-formation')]);
P('tuber','Tuber comes from Latin tuber, “swelling or lump”; in botany it names a thickened underground plant stem that stores food, such as a potato.',C('tuber.s1','植物块茎','A potato is a tuber that stores nutrients underground until the plant grows again.','马铃薯是一种块茎，在地下储存养分，等待植株再次生长。','potato tuber; underground tuber','名词，指植物地下膨大的储存养分的茎。','the potato is an enlarged underground stem.','植物块茎'),M('A potato is a tuber, which is the plant leaf that catches sunlight above ground.','A potato is a tuber, an underground swollen stem that stores food.','tuber指储存养分的地下膨大茎，不是叶片。','meaning'),[Q(1,'A potato tuber is…','a swollen underground stem that stores food','a flower petal above ground','a small boat','That is the botanical definition.','meaning'),Q(1,'What does the tuber store?','Nutrients for later growth','Sea water for a tsunami','Paint in a hollow tube','The example states its storage function.','context'),Q(1,'Which phrase is natural?','an underground tuber','a tuberly underground','underground a tuber of','Underground modifies the location of the tuber.','grammar'),Q(1,'Latin tuber meant…','swelling or lump','harbor wave','a legal promise','The botanical term reflects the swollen form.','word-formation')]);
P('tuberculosis','Tuberculosis is built from Latin tuberculum, “small swelling,” plus the disease-forming suffix -osis; it names an infectious bacterial illness that most often affects the lungs.',C('tuberculosis.s1','结核病','The clinic screened close contacts after a patient was diagnosed with tuberculosis.','一名患者确诊结核病后，诊所对密切接触者进行了筛查。','pulmonary tuberculosis; tuberculosis screening','名词，指主要由结核分枝杆菌引起、常累及肺部的传染病。','screening follows a confirmed infectious disease diagnosis.','结核病'),M('Tuberculosis is a harmless flower bulb that spreads by planting tulips.','Tuberculosis is an infectious bacterial disease that commonly affects the lungs.','结核病是传染性细菌疾病，不是植物球茎。','meaning'),[Q(1,'Tuberculosis is…','an infectious bacterial disease','a kind of flower bulb','a container for ice cream','That is the medical meaning.','meaning'),Q(1,'Why did the clinic screen close contacts?','A patient had the disease','A tulip was planted','A truck was loaded','The context links screening to possible infection.','context'),Q(1,'Which phrase is natural?','pulmonary tuberculosis','tuberculosisly pulmonary','pulmonary tuberculoses','Pulmonary modifies the disease name.','grammar'),Q(1,'The element tuberculum meant…','small swelling','harbor','truth','The Latin word refers to a small lump.','word-formation')]);
P('tuck','Tuck probably comes from a Germanic source reflected in Middle English tucken, “to draw or fold in”; it means push an edge into a space or make a sewn fold in cloth.',[C('tuck.s1','塞入/掖好','Please tuck your shirt into your trousers before the group photograph.','合影前请把衬衫下摆掖进裤子里。','tuck in a shirt; tuck something under','动词，指把松散边缘塞进衣物或其他空间里。','the shirt hem is pushed inside the waistband.','塞入/掖好'),C('tuck.s2','褶裥','The tailor added a small tuck at the waist to improve the fit of the dress.','裁缝在腰部加了一道小褶裥，让连衣裙更合身。','sewn tuck; make a tuck in fabric','名词，指缝在布料上的一道折褶。','the fabric is folded and sewn to shape the garment.','褶裥')],M('Please tuck your shirt out of the trousers so the hem remains securely inside the waistband.','Please tuck your shirt into your trousers so the hem is inside the waistband.','tuck in 表示塞进里面，错误句要求把衣摆留在外面。','meaning'),[Q(1,'To tuck a shirt in is to…','push its hem inside the waistband','cut its sleeves away','turn it into a tub','Sense 1 is the verb.','meaning'),Q(2,'A tuck sewn into a dress is…','a small folded section of fabric','a piece of metal pipe','a school audition','Sense 2 is a fabric fold.','context'),Q(1,'Which phrase is natural?','tuck the blanket under the mattress','tuck the blanket overly mattress','tuck underly the blanket to mattress','Under introduces where the loose edge is pushed.','grammar'),Q(1,'The older verb tuck was associated with…','drawing or folding something in','speaking the truth','riding an underground train','The historical meaning matches the folding-in sense.','word-formation')]);
P('Tuesday','Tuesday comes from Old English Tiwesdæg, “Tiw’s day,” named for the Germanic god Tiw, corresponding to the Roman god Mars.',C('Tuesday.s1','星期二','The safety inspection has been moved to Tuesday, the day after Monday.','安全检查改到了星期二，也就是星期一之后的一天。','on Tuesday; Tuesday morning; next Tuesday','名词，指星期一后的星期二。','the sentence identifies the weekday by its position in the week.','星期二'),M('The inspection is on Tuesday, the day immediately before Monday.','The inspection is on Tuesday, the day after Monday.','Tuesday在Monday之后而不是之前。','meaning'),[Q(1,'Tuesday is…','the day after Monday','the day before Monday','the last month of the year','That is its position in the week.','meaning'),Q(1,'When is the inspection now?','On Tuesday','On Thursday','At the end of the year','The context states the rescheduled day.','context'),Q(1,'Which phrase is standard?','on Tuesday morning','in Tuesday morning','at the Tuesday mornings','The preposition on is used with named days.','grammar'),Q(1,'Old English Tiwesdæg meant…','Tiw’s day','harbor wave','truth day','The weekday was named for the Germanic god Tiw.','word-formation')]);
P('tug','Tug is recorded in Middle English around 1200 from a weak form of Old English teohan, “pull, handle roughly, drag”; it means pull hard and suddenly, or a sudden pull, and later named a boat that tows ships.',[C('tug.s1','猛拉','The child tugged at his father’s sleeve to get his attention.','孩子猛拉父亲的袖子，想引起他的注意。','tug at/on a rope; tug hard','动词，指用力而突然地拉。','the child gives the sleeve a firm pull.','猛拉'),C('tug.s2','一拉/拖船','The tug guided the damaged cargo ship into the harbour.','拖船把受损的货船引入港口。','give something a tug; harbour tug','名词，可指突然的一拉，也可指拖曳船只的小型动力船。','the small boat tows the larger ship.','拖船')],M('The child tugged gently without pulling the sleeve at all.','The child tugged hard at the sleeve to get attention.','tug强调用力拉扯，原句说完全没有拉动。','meaning'),[Q(1,'To tug at a sleeve is to…','pull it firmly and suddenly','fold it into a sewn pleat','ride a train underground','Sense 1 is the pulling action.','meaning'),Q(2,'A harbour tug is…','a small boat that tows ships','a flower bulb','a legal property arrangement','Sense 2 names the vessel.','context'),Q(1,'Which phrase is natural?','give the rope a tug','give the rope a tuggingly','give to rope a tug at','Give something a tug is a common noun phrase.','collocation'),Q(1,'The precise origin of tug is…','uncertain, though Scandinavian parallels are suggested','certainly Japanese for harbor wave','certainly Latin for swelling','The history is not settled enough for a definite root.','word-formation')]);
P('tuition','Tuition comes from Latin tuitionem, “guardianship or protection,” from tueri, “watch over”; it now means fees for teaching or the teaching itself, especially individual instruction.',[C('tuition.s1','学费','The university raised tuition for next year, but it expanded its need-based grants.','大学提高了明年的学费，但也增加了按需发放的助学金。','pay tuition; tuition fees; college tuition','名词，指学校或学院收取的教学费用。','the university charges students for instruction.','学费'),C('tuition.s2','辅导教学','Mina receives private tuition in mathematics twice a week.','米娜每周接受两次数学私人辅导。','private tuition; tuition in a subject','名词，指教学活动，尤指一对一或小班辅导。','a tutor teaches one learner in a subject.','辅导教学')],M('The university lowered tuition, meaning the amount students must pay for instruction increased.','The university lowered tuition, meaning students pay less for instruction.','tuition作为学费时，降低费用不意味着学生需付更多。','meaning'),[Q(1,'University tuition usually means…','the fees paid for teaching','a boat that tows ships','a sudden pull','Sense 1 is the cost.','meaning'),Q(2,'Private tuition in mathematics is…','individual or small-group teaching','money held in a legal trust','an underground railway ride','Sense 2 is instruction.','context'),Q(1,'Which phrase is natural?','tuition in mathematics','mathematics tuitioning of','tuition to mathematicsly','In introduces the subject taught.','grammar'),Q(1,'The Latin source tuitionem referred to…','guardianship or protection','a flower','a weekday','The word began with a sense of watching over.','word-formation')]);
P('tulip','Tulip came through French tulipe from Turkish tülbent, “turban,” ultimately from Persian dulband; the flower name was linked to its turban-like shape, though the borrowing path is complex.',[C('tulip.s1','郁金香','The park is full of red tulips in April, just as the spring festival begins.','四月春季庆典开始时，公园里开满了红色郁金香。','red/yellow tulip; tulip bulb','名词，指春季开花、花冠常呈杯状的植物。','the flowers bloom in the park during spring.','郁金香'),C('tulip.s2','郁金香球根','Gardeners store each tulip in a cool dry place until it is time to plant it in autumn.','园丁把每个郁金香球根存放在阴凉干燥处，等到秋天再种。','plant tulip bulbs; store tulips over winter','名词，指秋植、次年开花的郁金香球根。','the bulb is stored for later planting.','郁金香球根')],M('The red tulip bloomed in April as a large underground stem that stored food.','The red tulip bloomed in April as a cup-shaped spring flower.','盛开的郁金香是花，不是地下储存养分的块茎。','meaning'),[Q(1,'A tulip is…','a spring-flowering plant with a cup-shaped flower','a swollen potato stem','a weekday','Sense 1 is the flower.','meaning'),Q(2,'What is stored until autumn for planting?','The tulip bulb','The flower petals','A brass trumpet','Sense 2 is the bulb.','context'),Q(1,'Which phrase is natural?','a yellow tulip bulb','a yellow tuliply bulb','a bulb yellow tulippingly','The color adjective and noun phrase are in normal order.','grammar'),Q(1,'The flower name was linked to a Turkish word for…','turban','harbor wave','pulling a rope','The flower was associated with a turban-like shape.','word-formation')]);
P('tumble','Tumble is an English word of uncertain deeper origin; it means fall suddenly, drop sharply in amount, or a fall and can describe a confused pile.',[C('tumble.s1','跌倒/翻滚','The toddler tumbled off the low chair onto a thick rug.','蹒跚学步的孩子从矮椅上摔下来，落在厚地毯上。','tumble down/off; tumble over','动词，指突然跌倒或翻滚着落下。','the child falls from the chair onto the rug.','跌倒/翻滚'),C('tumble.s2','骤降','Oil prices tumbled after the supply agreement was announced.','供应协议公布后，油价大幅下跌。','prices/markets tumble; tumble by','动词，指价格或数量快速下降。','the prices drop sharply.','骤降'),C('tumble.s3','摔倒/乱堆','She took a tumble on the icy path and landed in a tumble of fallen leaves.','她在结冰的小路上摔了一跤，落进一堆散落的树叶里。','take a tumble; a tumble of clothes','名词，指一次摔倒或杂乱堆在一起的东西。','the person falls, and the leaves form a loose heap.','摔倒/乱堆')],M('The toddler tumbled off the chair but remained safely seated on it without falling.','The toddler tumbled off the chair and landed on the rug.','tumble off指突然跌落，不能说人完全没有跌下。','meaning'),[Q(1,'The toddler tumbled off the chair means the child…','fell suddenly from it','sat still on it','put it in the car trunk','Sense 1 is a fall.','meaning'),Q(2,'Prices tumbled after the announcement means they…','fell sharply','rose slowly','became truthful','Sense 2 concerns a rapid decrease.','context'),Q(3,'Take a tumble means…','have a fall','give a lesson','make a trumpet sound','Sense 3 is the noun phrase for a fall.','meaning'),Q(1,'Which phrase is natural?','prices tumbled by ten percent','prices tumbled up by ten percent','prices tumbled ten percentsly','By introduces the size of a decrease.','grammar')]);
P('tumbler','Tumbler is formed from tumble plus the agent suffix -er; it names an acrobat who turns over and, separately, a straight-sided drinking glass without a handle.',[C('tumbler.s1','翻筋斗者','The young tumbler completed a forward roll and landed neatly on the mat.','年轻的翻筋斗者完成了一个前滚翻，稳稳落在垫子上。','circus tumbler; acrobat and tumbler','名词，指翻滚或做筋斗的表演者。','the performer turns over during the act.','翻筋斗者'),C('tumbler.s2','平底玻璃杯','Please pour the juice into a clean tumbler without a handle.','请把果汁倒进一个干净的无柄平底玻璃杯里。','a glass tumbler; tumbler of water','名词，指通常无柄、侧壁较直的饮水杯。','the vessel holds juice and has no handle.','平底玻璃杯')],M('She poured the juice into a tumbler, a handled cooking pot used on the stove.','She poured the juice into a tumbler, a straight-sided drinking glass without a handle.','此处 tumbler 指无柄饮水杯，不是带柄炖锅。','meaning'),[Q(1,'A circus tumbler is…','an acrobat who turns over','a person who studies a disease','a court jury','Sense 1 is the performer.','meaning'),Q(2,'What did the juice go into?','A straight-sided glass without a handle','A tree trunk','A harbor wave','Sense 2 is the drinking vessel.','context'),Q(1,'Which phrase is natural?','a tumbler of water','a tumbler waterly','a water at tumbler of','Of expresses the contents of the glass.','grammar'),Q(1,'The suffix -er in tumbler identifies…','a performer who tumbles','a person who gives tuition','a swelling in a plant','It forms an agent noun from tumble.','word-formation')]);
P('tumid','Tumid comes from Latin tumidus, “swollen,” from tumere, “to swell”; it describes a body swollen with fluid or language made pompously inflated.',C('tumid.s1','肿胀/浮夸','The doctor noted a tumid ankle, while the editor cut the essay’s tumid prose.','医生注意到脚踝肿胀，而编辑删去了文章浮夸的文字。','tumid tissue; tumid prose/style','形容词，指肿胀的，也可指语言夸张、浮华的。','the word applies to physical swelling and inflated writing.','肿胀/浮夸'),M('The essay used tumid prose, which was plain, concise, and free of exaggeration.','The essay used tumid prose, which was pompous and overblown.','tumid形容文风时表示浮夸，不是简洁平实。','meaning'),[Q(1,'Tumid language is…','pompously exaggerated','plain and concise','a legal trust','That is the figurative sense.','meaning'),Q(1,'What was physically tumid?','The patients ankle','The essay title','A radio station','The context identifies a swollen body part.','context'),Q(1,'Which phrase is natural?','tumid prose','prose tumidly as a noun','a tumid of prose','Tumid is an adjective modifying prose.','grammar'),Q(1,'Latin tumere meant…','to swell','to turn a lathe','to trust','Tumid retains the idea of swelling.','word-formation')]);
P('tumor','Tumor comes from Latin tumor, “swelling,” from tumere, “to swell”; in medicine it names an abnormal mass of cells, which may be benign or malignant.',C('tumor.s1','肿瘤','The scan showed a small tumor, and the specialist ordered further tests to identify it.','影像显示一个小肿瘤，专科医生安排了进一步检查以确定其性质。','brain/lung tumor; remove a tumor','名词，指由异常细胞生长形成的肿块，性质需由医学检查确定。','additional tests are needed to characterize the abnormal growth.','肿瘤'),M('The scan showed a tumor, a normal collection of healthy cells that required no medical evaluation.','The scan showed an abnormal cell growth that needed medical evaluation.','tumor指异常细胞形成的肿块，不能直接等同于正常组织。','meaning'),[Q(1,'A tumor is…','an abnormal mass of cells','a normal group of healthy cells only','a musical note pattern','That is the medical meaning.','meaning'),Q(1,'Why were further tests ordered?','To identify the nature of the small tumor','To tune a radio','To inspect a sports field','The context says testing would characterize the finding.','context'),Q(1,'Which phrase is natural?','a brain tumor','a brain tumorously','a tumor of brainly','Brain modifies the kind of tumor.','grammar'),Q(1,'Latin tumor originally meant…','swelling','a great crowd noise','a sea wave','The medical word reflects a lump or swelling.','word-formation')]);
P('tumult','Tumult came from Latin tumultus, “uproar or confusion”; it describes disorder in an excited crowd and can also mean the loud collective noise they make.',[C('tumult.s1','骚乱','The announcement caused a tumult in the square as people rushed toward the exits.','消息一公布，广场上人群朝出口涌去，顿时一片混乱。','cause/create a tumult; political tumult','名词，指激动人群引起的混乱和骚动。','the crowd becomes disorderly and confused.','骚乱'),C('tumult.s2','喧闹声','The tumult of the market made it difficult to hear the guide.','市场里人声鼎沸，导游的话很难听清。','the tumult of voices/crowds; amid the tumult','名词，指许多人同时喊叫或活动发出的巨大喧闹声。','many voices combine into loud noise.','喧闹声')],M('The announcement caused a tumult, yet the crowd remained silent, orderly, and perfectly still.','The announcement caused a tumult as the excited crowd rushed and shouted.','tumult指骚动或喧闹，完全安静有序与之相反。','meaning'),[Q(1,'A tumult in a square is…','confusion and disorder among an excited crowd','a calm and empty street','a type of underground passage','Sense 1 is disorder.','meaning'),Q(2,'The tumult of the market refers to…','the loud noise of many people','one quiet conversation','a swollen ankle','Sense 2 emphasizes sound.','context'),Q(1,'Which phrase is natural?','amid the tumult of the crowd','amid tumultly crowd at','the tumult amongly of crowd','Of identifies what produces the noise.','grammar'),Q(1,'Latin tumultus referred to…','uproar or confusion','truth or honesty','a tree stem','The historical word also described public disorder.','word-formation')]);
P('tuna','The American English form tuna came from Spanish tuna; Spanish atún came from Arabic tun, probably borrowed in Spain from Latin thunnus, ultimately Greek thynnos. The word names a large fast ocean fish and its meat.',C('tuna.s1','金枪鱼','We made sandwiches with tuna, lemon, and chopped celery for the picnic.','我们用金枪鱼、柠檬和切碎的芹菜做了野餐三明治。','fresh/tinned tuna; tuna salad','名词，指鲭科大型海鱼，也指这种鱼的肉。','the ingredient in the sandwiches is the fish meat.','金枪鱼'),M('The salad was made with tuna, a land-growing yellow spice rather than fish.','The salad was made with tuna, the meat of a large ocean fish.','tuna指金枪鱼或其鱼肉，不是香料。','meaning'),[Q(1,'Tuna is…','a large ocean fish or its meat','a plant root used as dye','a kind of tree stem','That is the dictionary sense.','meaning'),Q(1,'What was mixed into the sandwiches?','Tuna, lemon, and celery','Turmeric and paint','Ice cream and a tube','The context lists the ingredients.','context'),Q(1,'Which phrase is natural?','tinned tuna','tuna tinningly','a tinned of tuna','Tinned modifies the preserved fish.','grammar'),Q(1,'The word reached English through…','Spanish atún from Arabic al-tūn','Old English Tiwesdæg','Latin tueri meaning protect','That is the proposed borrowing route.','word-formation')]);
P('tundra','Tundra came through Russian tundra from a Sami word for a treeless upland; it names cold, open land where the ground remains frozen, or a region of this terrain.',[C('tundra.s1','苔原地带','Reindeer graze on the tundra in summer, when low plants emerge above the frozen ground.','夏季冻土表面长出低矮植物时，驯鹿在苔原上觅食。','Arctic tundra; tundra vegetation','名词，指寒冷、无树且地面长期冻结的开阔地区。','the landscape is treeless and underlain by permafrost.','苔原地带'),C('tundra.s2','一片苔原','The tundras of northern Siberia extend across several thousand kilometres.','西伯利亚北部的一片片苔原绵延数千公里。','tundras of Siberia; a region of tundra','名词，指一片具体的苔原地带。','the plural refers to separate areas of this terrain.','一片苔原')],M('The tundra was a warm, dense tropical forest with no frozen ground.','The tundra was a cold, treeless plain with permanently frozen ground.','冻土、无树是苔原的典型特征，与热带森林相反。','meaning'),[Q(1,'Tundra is…','cold treeless land with frozen ground','a warm dense rainforest','a yellow cooking powder','Sense 1 describes the landscape.','meaning'),Q(2,'The tundras of Siberia means…','several areas of this frozen terrain','several underground trains','a set of musical notes','Sense 2 refers to regions.','context'),Q(1,'Which phrase is natural?','Arctic tundra','tundra the arcticly','an Arctic of tundra','Arctic modifies the type or location of tundra.','grammar'),Q(1,'The word reached English through Russian from…','a Sami word for treeless upland','Japanese for harbor wave','Latin for a small swelling','The source is associated with northern open terrain.','word-formation')]);
P('tune','Tune came through Middle English and French from Latin tonus, “tone,” ultimately Greek tonos; it names a memorable sequence of notes and means adjust an instrument, radio, or engine.',[C('tune.s1','曲调','I recognize the tune from the concert, although I cannot remember its title.','我认得音乐会上的那段曲调，却想不起曲名。','a familiar tune; sing/play a tune','名词，指悦耳且容易记住的一串乐音。','the listener recognizes the melody.','曲调'),C('tune.s2','调准/调节','Tune the radio to the local news station before the traffic report begins.','交通新闻开始前，把收音机调到本地新闻台。','tune an instrument/radio/engine; tune to a station','动词，指调节设备使其发出正确音高或接收到特定信号。','the radio is adjusted to receive a chosen station.','调准/调节')],M('Tune the radio to the local news station, but leave it set to a different frequency.','Tune the radio to the local news station by adjusting it to that frequency.','tune to a station表示调到指定频率，不能仍留在别的频率。','meaning'),[Q(1,'A tune is…','a pleasant, memorable series of musical notes','a sudden fall in prices','a frozen treeless landscape','Sense 1 is the melody.','meaning'),Q(2,'Tune the radio to the news means…','adjust it so it receives that station','turn it into a drinking glass','make it louder without changing any setting','Sense 2 is the verb.','context'),Q(1,'Which phrase is natural?','tune the piano before the concert','tune the piano into the concert','tune to piano the before','Tune an instrument means adjust it.','grammar'),Q(1,'The Latin source tonus referred to…','tone','a turban','a boat','The musical sense is connected with tone.','word-formation')]);
P('tuning','Tuning is formed from tune plus -ing; it names the act of adjusting a musical instrument, or adjusting a radio or television to receive a chosen station.',[C('tuning.s1','乐器调音','The piano needs tuning before Saturday’s recital because several notes sound flat.','钢琴在周六的独奏会前需要调音，因为有几个音偏低。','piano tuning; tuning fork; need tuning','名词，指调整乐器以使其音高准确的过程。','the instrument is adjusted before performance.','乐器调音'),C('tuning.s2','调谐','Accurate tuning helps the receiver pick up the weak station clearly.','准确调谐有助于接收器清晰接收信号较弱的电台。','radio/receiver tuning; fine tuning','名词，指调节收音机或电视以接收特定频道或信号。','the receiver is adjusted to a selected frequency.','调谐')],M('The piano needs tuning, although every note is already perfectly in pitch.','The piano needs tuning because several notes sound flat.','此处需要调音是因为音高不准，完全准确则不构成所述问题。','meaning'),[Q(1,'Piano tuning is…','adjusting its notes to the correct pitch','writing a legal document','storing paint in a tube','Sense 1 is musical adjustment.','meaning'),Q(2,'Accurate radio tuning helps a receiver…','pick up a selected station','produce a flower bulb','cause a crowd tumult','Sense 2 is signal adjustment.','context'),Q(1,'Which phrase is natural?','the piano needs tuning','the piano needs to tuningly','the piano tuning need','Need can be followed by the noun tuning.','grammar'),Q(1,'Tuning is formed from…','tune plus -ing','tundra plus -er','tuberculosis plus -al','The suffix names the process of adjusting.','word-formation')]);
P('tunnel','Tunnel came through French tonnel, “barrel or tunnel,” a diminutive related to tonne; it names an underground passage and also means dig such a passage.',[C('tunnel.s1','隧道','The train passed through a tunnel under the hill and emerged beside the river.','火车穿过山下的隧道，在河边驶出。','railway/road tunnel; pass through a tunnel','名词，指穿过地下或山体的长通道。','the train travels through an enclosed passage.','隧道'),C('tunnel.s2','挖隧道','Workers tunnelled through the rock to create a route for the new water pipe.','工人们凿穿岩石，为新水管开辟通道。','tunnel through rock; tunnel under a road','动词，指挖掘或开凿隧道。','the workers dig a passage in the rock.','挖隧道')],M('The train passed through a tunnel that was open countryside with no enclosed passage.','The train passed through an underground passage cut beneath the hill.','tunnel作为名词指封闭通道，不是露天田野。','meaning'),[Q(1,'A railway tunnel is…','a long passage through or under ground','an open field beside the railway','a radio frequency','Sense 1 is the passage.','meaning'),Q(2,'Workers tunnelled through the rock means they…','dug a passage through it','tuned a piano','pulled a rope suddenly','Sense 2 is the verb.','context'),Q(1,'Which phrase is natural?','a tunnel under the hill','a tunnel underly the hill','a tunnel of under hill','Under marks the route beneath the hill.','grammar'),Q(1,'The earlier French source tonnel referred to…','a barrel or tunnel','a yellow flower','a court case','The English word developed through French.','word-formation')]);
P('turbid','Turbid comes from Latin turbidus, “muddy or disturbed,” related to turba, “confusion”; it describes liquid that is unclear because suspended matter is mixed through it.',C('turbid.s1','浑浊','After the flood, the river ran turbid and brown with mud and silt.','洪水过后，河水因混入泥沙而变得浑浊发褐。','turbid water; turbid river; become turbid','形容词，指液体因含有悬浮物而不清澈的。','mud and silt cloud the water.','浑浊'),M('After the flood, the river ran turbid and perfectly clear, with no particles in the water.','After the flood, the river ran turbid and brown with suspended mud.','turbid意为浑浊，与清澈且没有颗粒相反。','meaning'),[Q(1,'Turbid water is…','cloudy with matter suspended in it','perfectly clear and pure','moving in a circle as a turbine','That is the physical sense.','meaning'),Q(1,'Why was the river turbid after the flood?','Mud and silt were suspended in it','It had been tuned to a station','A crowd was shouting','The context explains the cloudiness.','context'),Q(1,'Which phrase is natural?','turbid water','water turbidityly','a turbid of water','Turbid is an adjective modifying water.','grammar'),Q(1,'Latin turbidus meant…','muddy or disturbed','a trumpet player','a harbor wave','The modern adjective preserves the muddy sense.','word-formation')]);
P('turbine','Turbine comes from French turbine and Latin turbo, “whirling top”; it names a machine with rotating blades driven by steam, gas, water, or wind, or an engine using one.',[C('turbine.s1','涡轮机','The factory uses a gas turbine to generate electricity during peak demand.','工厂在用电高峰时使用燃气涡轮机发电。','gas/wind turbine; turbine blades','名词，指由流体推动叶片旋转来传递能量的机器。','gas flow rotates the blades to produce power.','涡轮机'),C('turbine.s2','涡轮发动机','The aircraft is powered by a turbine that compresses air and burns fuel.','这架飞机由涡轮发动机提供动力，该发动机压缩空气并燃烧燃料。','turbine engine; aircraft turbine','名词，指包含涡轮、用于飞机或发电设备的发动机。','the aircraft engine uses a turbine.','涡轮发动机')],M('The turbine generated power with blades that remained still while no fluid moved.','The turbine generated power as flowing gas spun its blades.','涡轮机依靠流体驱动叶片旋转；静止叶片无法完成此过程。','meaning'),[Q(1,'A turbine is a machine with…','rotating blades driven by a fluid','a flat screen for watching television','a container for ice cream','Sense 1 describes the machine.','meaning'),Q(2,'What powers the aircraft in the example?','A turbine engine','A flower bulb','A legal trust','Sense 2 is the engine use.','context'),Q(1,'Which phrase is natural?','wind turbine blades','windy turbine to blades','a turbine windly blade','Wind modifies the kind of turbine.','grammar'),Q(1,'Latin turbo referred to a…','whirling top','frozen landscape','weekday','The name alludes to rotation.','word-formation')]);
P('turbulence','Turbulence comes from Latin turbulentia, from turbulentus, “agitated or disorderly”; it means irregular movement in a fluid or a period of unrest and instability.',C('turbulence.s1','湍流/动荡','The plane dropped suddenly in clear-air turbulence over the mountains.','飞机在山脉上空遭遇晴空湍流，突然下坠。','air turbulence; political turbulence; turbulence in a fluid','名词，指流体的不规则运动，也可指动荡不安的时期。','irregular air flow jolts the aircraft.','湍流/动荡'),M('The plane dropped suddenly in turbulence, although the air was perfectly smooth and motionless.','The plane dropped suddenly because irregular air currents caused turbulence.','turbulence指不规则流动，不能同时描述完全平稳静止的空气。','meaning'),[Q(1,'Air turbulence is…','irregular movement in the air','a stable, motionless flow','a type of flower','That is the physical sense.','meaning'),Q(1,'Why did the plane drop?','It entered irregular air currents','It was placed in a car trunk','The crew tuned a piano','The context links the drop to turbulent air.','context'),Q(1,'Which phrase is natural?','political turbulence','political turbulently as noun','a turbulence politicals','Turbulence is a noun naming instability.','grammar'),Q(1,'Latin turbulentus meant…','agitated or disorderly','a dependable person','a swollen plant stem','Turbulence names agitation or irregular motion.','word-formation')]);
P('turbulent','Turbulent comes from Latin turbulentus, “agitated or disorderly”; it describes confused periods of change or violent, uneven movement in air or water.',[C('turbulent.s1','动荡的','It was a turbulent year in politics, with three governments changing in quick succession.','那是政治动荡的一年，三个政府接连更替。','turbulent period/year; turbulent politics','形容词，指充满混乱、变化或动荡的。','the rapid government changes create instability.','动荡的'),C('turbulent.s2','湍急的','The boat struggled in turbulent water near the rocky shore.','小船在岩岸附近的湍流中艰难前行。','turbulent water/air; turbulent flow','形容词，指空气或水流动剧烈而不平稳的。','the water moves violently and unevenly.','湍急的')],M('The boat crossed turbulent water that was completely smooth and still.','The boat struggled through turbulent water with strong, uneven currents.','turbulent形容不平稳且剧烈的水流，不是静止水面。','meaning'),[Q(1,'A turbulent political year is…','full of disorder and rapid change','calm and completely stable','a day after Monday','Sense 1 concerns instability.','meaning'),Q(2,'Turbulent water moves…','violently and unevenly','without any motion','only underground','Sense 2 is the physical flow.','context'),Q(1,'Which phrase is natural?','a turbulent flight','a turbulence flightly','a flight turbulentness','Turbulent is the adjective modifying flight.','grammar'),Q(1,'Turbulent is historically associated with Latin for…','agitated or disorderly','whirling top','tree stem','The Latin adjective describes disorder and agitation.','word-formation')]);
P('turf','Turf comes from Old Norse torf, “grass and earth”; it names a layer of grass with soil attached and, figuratively, ground a person or group claims to control.',[C('turf.s1','草皮','The players slipped on the wet turf during the final minutes of the match.','比赛最后几分钟，球员们在潮湿的草皮上滑倒。','artificial/natural turf; lay turf','名词，指带有土层的草皮，常用于覆盖场地。','the grass-and-soil surface is slippery.','草皮'),C('turf.s2','地盘','The two gangs argued over whose turf included the market street.','两个帮派争论市场街究竟属于谁的地盘。','defend/claim one’s turf; on someone else’s turf','名词，比喻个人或团体声称并保护的活动范围或地盘。','the groups dispute control of an area.','地盘')],M('The players slipped on the turf, which was bare concrete without grass or soil.','The players slipped on the turf, the wet layer of grass covering the field.','此处 turf指球场草皮，不是裸露的混凝土。','meaning'),[Q(1,'Turf on a sports field is…','grass together with its underlying soil','a metal pipe','a courtroom','Sense 1 is the surface.','meaning'),Q(2,'A gang defending its turf is defending…','an area it claims to control','a flower bulb','a radio frequency','Sense 2 is figurative territory.','context'),Q(1,'Which phrase is natural?','wet turf','wetly turfing','turf of wetly','Wet is an adjective modifying the noun.','grammar'),Q(1,'Old Norse torf referred to…','grass and earth','a musical tone','a legal fee','The older word named the sod itself.','word-formation')]);
P('turkey','Turkey was named through the historical trade route that brought the bird to English speakers, who associated it with Turkey; it names the large bird, its meat, or a complete failure.',[C('turkey.s1','火鸡/火鸡肉','We served roast turkey with vegetables at the family dinner.','家庭晚餐上，我们端上了烤火鸡和蔬菜。','roast turkey; turkey meat; wild turkey','名词，指大型火鸡，也指其肉。','the dish is made from the bird.','火鸡/火鸡肉'),C('turkey.s2','失败作品','The studio expected a hit, but the film turned out to be a turkey.','制片厂原本期待大获成功，但这部电影结果成了失败之作。','a box-office turkey; turn out to be a turkey','名词，非正式用法，指彻底失败的作品或项目。','the film performs badly rather than succeeding.','失败作品')],M('The film was a turkey, meaning it became the studio’s most successful release of the year.','The film was a turkey, meaning it failed badly at the box office.','非正式比喻 turkey指失败作品，与大获成功相反。','meaning'),[Q(1,'Roast turkey is…','cooked meat from a large bird','a yellow root powder','a machine with rotating blades','Sense 1 is food.','meaning'),Q(2,'A film that is a turkey…','fails badly','wins every major award','takes the London Underground','Sense 2 is informal figurative use.','context'),Q(1,'Which phrase is natural?','a box-office turkey','a turkey box-officing','a box office of turkeying','Box-office modifies the kind of failure.','grammar'),Q(1,'The bird was named in English through an association with…','Turkey and historical trade routes','the Germanic god Tiw','the Latin word for swelling','The name reflects how the bird reached English trade.','word-formation')]);
P('turmeric','Turmeric entered English through medieval forms whose route is debated, often traced through Arabic kurkum; it is the bright yellow powder from the rhizome of Curcuma longa.',C('turmeric.s1','姜黄','She stirred turmeric into the rice, turning it a warm golden color.','她把姜黄粉拌进米饭，使米饭呈现温暖的金黄色。','ground turmeric; turmeric powder; turmeric rice','名词，指姜黄根茎制成的黄色香料，也用于染色。','the powder colors the rice yellow.','姜黄'),M('She stirred turmeric into the rice, but it turned bright blue.','She stirred turmeric into the rice, and the yellow spice turned it golden.','姜黄通常呈亮黄色并使食物染黄，不会把米饭变蓝。','meaning'),[Q(1,'Turmeric is…','a bright yellow spice from a plant rhizome','a bird often roasted for dinner','a cold treeless region','That is the dictionary sense.','meaning'),Q(1,'What color did the turmeric make the rice?','Golden yellow','Bright blue','Transparent','The example explicitly says it turned gold.','context'),Q(1,'Which phrase is natural?','ground turmeric','turmericly ground','a ground of turmericly','Ground is an adjective for the powdered spice.','grammar'),Q(1,'The borrowing history of turmeric is…','complex, often linked through Arabic kurkum','certainly from Old English Tiwesdæg','from Japanese for harbor wave','The exact route is debated, so the claim is appropriately cautious.','word-formation')]);
P('turmoil','Turmoil is recorded in English from the sixteenth century, but its deeper origin is uncertain; it means a state of great confusion, uncertainty, or trouble.',C('turmoil.s1','混乱/动荡','The country was in turmoil after the election results were challenged.','选举结果受到质疑后，全国陷入动荡。','political/economic turmoil; in turmoil','名词，指严重的混乱、不确定或困境。','the dispute creates widespread instability.','混乱/动荡'),M('The country was in turmoil, with every institution calm, settled, and free from uncertainty.','The country was in turmoil because institutions faced confusion and uncertainty.','turmoil表示严重动荡，与安定且毫无不确定性相反。','meaning'),[Q(1,'A country in turmoil is…','in great confusion or uncertainty','completely stable and predictable','full of spring flowers','That is the meaning of the noun.','meaning'),Q(1,'What caused turmoil in the example?','The election results were challenged','The radio was tuned','A child tugged a sleeve','The sentence identifies the political dispute.','context'),Q(1,'Which phrase is natural?','economic turmoil','economical turmoilingly','turmoil economic of','Economic modifies the type of turmoil.','grammar'),Q(1,'The deeper origin of turmoil is…','uncertain','definitely Japanese for harbor','definitely Latin for trust','The history is obscure, so no unsupported root is stated.','word-formation')]);
P('turn','Turn comes through Old French tourner from Latin tornare, “shape on a lathe,” ultimately Greek tornos; it means change direction, become or make something different, or a chance in sequence.',[C('turn.s1','转向','Turn left at the lights, then continue for two blocks.','在红绿灯处左转，然后继续走两个街区。','turn left/right; turn around','动词，指改变朝向或行进方向。','the route changes direction at the lights.','转向'),C('turn.s2','变成','The leaves turn red when the nights become colder.','夜晚变冷时，树叶会变红。','turn red/cold; turn into','动词，指变成某种状态或使其变成某种状态。','the leaves change color.','变成'),C('turn.s3','轮次','It is your turn to choose the next song for the group.','轮到你为大家选下一首歌了。','take turns; wait your turn; turn to speak','名词，指按顺序轮到某人做某事的机会。','the group proceeds in sequence.','轮次')],M('Turn left at the lights, then continue along the road without changing direction.','Turn left at the lights, then follow the new direction.','turn left要求改变行进方向，不能同时保持原方向不变。','meaning'),[Q(1,'Turn left means…','change direction toward the left','become red','wait for your chance','Sense 1 is direction.','meaning'),Q(2,'The leaves turn red means they…','change into a red color','are rotated by a machine','are a legal trust','Sense 2 is a change of state.','context'),Q(3,'It is your turn means…','you have the next chance in sequence','you must turn the radio off','you are in a tunnel','Sense 3 is an assigned opportunity.','meaning'),Q(1,'Which phrase is natural?','turn left at the lights','turn left to the lights ating','left turn to the lights at','At identifies the location of the turn.','grammar')]);
P('turn into','Turn into combines turn with into and means change into another state or type, or cause someone or something to change into another form.',[C('turn into.s1','转变成','The quiet village turned into a busy town after the new railway opened.','新铁路开通后，安静的村庄变成了一座繁忙的城镇。','turn into a city; turn into a problem','动词短语，指人或事物变成另一种状态或类型。','the village changes into a town.','转变成'),C('turn into.s2','使变成','The frost turned the wet leaves into a thin carpet of ice.','霜冻使湿树叶变成了一层薄薄的冰毯。','turn something into something; turn water into ice','动词短语，指使某物转变成另一种形态。','the frost causes the change in the leaves.','使变成')],M('The village turned into a busy town, but it remained completely unchanged and undeveloped.','The village turned into a busy town as new buildings and businesses appeared.','turn into表达状态转变，与完全没有变化相矛盾。','meaning'),[Q(1,'The village turned into a town means it…','changed and became a town','stayed exactly the same','was tuned to a station','Sense 1 is the subject changing.','meaning'),Q(2,'Frost turned leaves into ice means frost…','caused the leaves to change form','watched the leaves without affecting them','made them part of a courtroom','Sense 2 has a causing object.','context'),Q(1,'Which structure is correct?','turn water into ice','turn into water ice','turn water to into ice','The pattern is turn something into something.','grammar'),Q(1,'Into marks…','the resulting state or form','the original location only','a person who performs an action','The phrase identifies what something becomes.','word-formation')]);
P('turn off','Turn off is a phrasal verb meaning switch off a device, make someone lose interest, or leave a main road for a smaller route.',[C('turn off.s1','关闭','Please turn off the lamp before you leave the study.','离开书房前请把灯关掉。','turn off a light/machine; turn the tap off','动词短语，指切断设备、电灯或水源。','the lamp is switched to the off state.','关闭'),C('turn off.s2','使失去兴趣','The long, technical speech turned the audience off before the final section.','冗长而专业的演讲还没到最后一部分就让观众失去了兴趣。','turn someone off; be turned off by','动词短语，指使某人失去兴趣或感到反感。','the audience becomes bored and disengaged.','使失去兴趣'),C('turn off.s3','驶离主路','Turn off the highway at the next junction and follow the signs for the airport.','在下一个交叉口驶离高速公路，然后沿机场指示牌前行。','turn off at a junction; turn off the main road','动词短语，指从主路转入较小的道路。','the driver leaves the highway at the junction.','驶离主路')],M('Please turn off the lamp, leaving it fully lit and switched on.','Please turn off the lamp so it is no longer lit.','turn off设备表示关闭，保持点亮与指令相反。','meaning'),[Q(1,'Turn off the lamp means…','switch it so it stops giving light','make it brighter','leave the room by a side road','Sense 1 is switching off.','meaning'),Q(2,'The speech turned the audience off means it…','made them lose interest','made them more attentive','turned the lamp on','Sense 2 is figurative.','context'),Q(3,'Turn off at the junction means…','leave the main road there','stop listening to the speech','switch off the highway','Sense 3 is a route instruction.','meaning'),Q(1,'Which phrase is natural?','turn the lamp off','turn off the lamping','turn the off lamp at','The particle off can follow the object or the verb.','grammar')]);
P('turn out','Turn out can mean prove to be a certain way, go to an event in large numbers, switch off a light, or produce goods in a factory.',[C('turn out.s1','结果是','The alarm turned out to be false after the guard checked every room.','保安检查完每个房间后，结果发现那是一次误报。','turn out to be; it turns out that','动词短语，指最终证明或结果是某种情况。','the investigation establishes the actual result.','结果是'),C('turn out.s2','到场','Thousands turned out for the parade despite the cold rain.','尽管下着冷雨，仍有数千人到场观看游行。','turn out for an event; a large turnout','动词短语，指许多人前往参加或观看活动。','the crowd attends the parade.','到场'),C('turn out.s3','关灯/生产','The factory turns out aircraft parts, and workers turn out the lights at closing time.','这家工厂生产飞机零件，工人下班时会关灯。','turn out products; turn out the lights','动词短语，可指生产制造，也可指熄灯。','the sentence illustrates the production and switching-off uses.','关灯/生产')],M('The alarm turned out to be false, although the guard confirmed a real intruder in every room.','The alarm turned out to be false after no intruder was found.','turn out to be false表示最终证实为假，与确认真的入侵者相矛盾。','meaning'),[Q(1,'The alarm turned out to be false means it…','proved false after checking','was known to be true from the start','was turned into a machine','Sense 1 is the eventual result.','meaning'),Q(2,'Thousands turned out for the parade means they…','went to attend it','produced it in a factory','left the route at a junction','Sense 2 describes attendance.','context'),Q(3,'The factory turns out parts means it…','produces them','switches them off','makes people lose interest','Sense 3 is manufacturing.','meaning'),Q(1,'Which pattern is correct?','It turned out to be a false alarm.','It turned out being a false alarmly.','It turned to out a false alarm.','Turn out is followed by to be in this use.','grammar')]);
P('turn to','Turn to combines turn with to and means seek help or advice from someone, or open a book to a particular page or begin addressing a subject.',[C('turn to.s1','求助','When the grant application became confusing, she turned to her mentor for advice.','资助申请变得难以理解时，她向导师寻求建议。','turn to someone for help/advice; turn to a friend','动词短语，指遇到困难时向某人求助或征求意见。','the mentor is approached for guidance.','求助'),C('turn to.s2','翻到/转向话题','Turn to page twelve for the diagram, then we will turn to the final question.','请翻到第十二页看图，然后我们再讨论最后一个问题。','turn to page 12; turn to a topic','动词短语，指翻到书页或开始处理某个话题。','the reader opens the book at a specified page.','翻到/转向话题')],M('She turned to her mentor for advice, although she deliberately avoided asking anyone for help.','She turned to her mentor and asked for guidance.','turn to someone for advice就是向对方求助，不能同时说刻意避免求助。','meaning'),[Q(1,'Turn to a mentor for advice means…','ask the mentor for guidance','switch off the mentor','turn the mentor into a book','Sense 1 is seeking help.','meaning'),Q(2,'Turn to page twelve means…','open the book at that page','close the book without opening it','ask a mentor for help','Sense 2 is the page instruction.','context'),Q(1,'Which phrase is natural?','turn to a colleague for advice','turn a colleague to advice for','turn to for a colleague advice','For introduces the help being sought.','grammar'),Q(1,'The particle to here points toward…','a person or page approached','a completed switch-off','a sudden fall','The phrase describes directing oneself toward help or a page.','word-formation')]);
P('turn-off','Turn-off is a noun formed from the phrasal verb turn off; it names switching off a device or supply, something that discourages interest, or a junction leaving a main road.',[C('turn-off.s1','关闭装置','The turn-off for the power is behind the panel, next to the main switch.','电源关闭装置在面板后面，挨着总开关。','power turn-off; automatic turn-off','名词，指关闭机器或切断供应的操作或装置。','the switch interrupts the power supply.','关闭装置'),C('turn-off.s2','败兴事物','The slow opening of the film was a real turn-off for the audience.','电影开头节奏缓慢，着实让观众失去了兴趣。','a real turn-off; find something a turn-off','名词，指使人失去兴趣或感到反感的人或事。','the audience becomes disengaged.','败兴事物'),C('turn-off.s3','驶出路口','Take the next turn-off for the coast and follow the brown signs.','在下一个驶出路口转向海岸，再沿着棕色指示牌走。','take the next turn-off; motorway turn-off','名词，指车辆离开主干道的岔路口。','drivers leave the main route at that junction.','驶出路口')],M('The film was a turn-off because its opening kept the audience interested.','The film was a turn-off because its opening made the audience lose interest.','turn-off表示令人失去兴趣的事物；精彩开场吸引观众，不是败兴原因。','meaning'),[Q(1,'A power turn-off is…','an action or device that cuts the supply','a road to the coast','a film audience','Sense 1 concerns switching off.','meaning'),Q(2,'A film that is a turn-off…','makes viewers lose interest','is certain to be a great success','is a type of road junction','Sense 2 is the figurative noun.','context'),Q(3,'Take the next turn-off means…','leave the main road at the next junction','switch off the car headlights','turn the film into a show','Sense 3 is the road exit.','meaning'),Q(1,'Which phrase is natural?','a real turn-off','a turn-offly real','turn-off of realing','Real modifies the noun turn-off.','grammar')]);
P('turning','Turning is formed from turn plus -ing; as a noun, it means a place where one road branches away or the act of changing direction.',[C('turning.s1','岔路/转弯','Take the second turning on the left after you cross the bridge.','过桥后，在第二个左侧岔路口转弯。','take the first/second turning; a sharp turning','名词，指道路分岔处或改变行进方向的转弯。','the driver chooses a particular branch in the road.','岔路/转弯')],M('Take the second turning on the left, which means continue straight and ignore every branch.','Take the second turning on the left, where the road branches away.','turning是转弯或分岔口，不能指继续直行并忽略分支。','meaning'),[Q(1,'The second turning on the left is…','the second left-hand branch or junction','the second day of the week','a radio setting','That is the road sense.','meaning'),Q(1,'When should the driver turn?','After crossing the bridge','Before reaching the bridge','Only after the final destination','The example gives the landmark.','context'),Q(1,'Which phrase is natural?','take the second turning','take the second turningly','turning take second to','Take is used with a road turning.','grammar'),Q(1,'Turning is formed from…','turn plus -ing','tuna plus -ic','tub plus -er','The suffix creates the action or place noun.','word-formation')]);
P('turning point','Turning point combines turn and point; it means a decisive moment after which events develop differently, or the location where a road changes direction.',[C('turning point.s1','转折点','The first successful trial was a turning point in the research project.','第一次成功的试验成为这个研究项目的转折点。','a turning point in history/life; reach a turning point','名词，指促成重要变化、使后续发展不同的关键时刻。','the project progresses differently after the success.','转折点'),C('turning point.s2','道路拐点','The path turning point is just beyond the stone bridge.','小路的转弯处就在石桥后面。','a road/path turning point; mark the turning point','名词，指道路或小径改变方向的地点。','the route changes direction at that location.','道路拐点')],M('The trial was a turning point, but nothing changed afterward and the project followed exactly the same course.','The trial was a turning point because the project changed direction afterward.','比喻义的turning point意味着后续发展改变。','meaning'),[Q(1,'A turning point in a project is…','a moment that changes its later direction','a routine event with no effect','a container used for paint','Sense 1 is figurative.','meaning'),Q(2,'The path turning point is…','the place where the path changes direction','a moment of political change','a power switch','Sense 2 is literal.','context'),Q(1,'Which phrase is standard?','a turning point in her career','a turning point of in her career','a career turningly point','In introduces the area of change.','grammar'),Q(1,'The compound turning point combines…','a change of direction with a location or moment','a flower with a root','a weekday and a month','The image of turning marks a change in course.','word-formation')]);
P('turnip','Turnip comes from Middle English turnepe, probably combining turne, “round,” with nepe, related to Latin napus, “turnip”; it is a plant grown for its edible swollen root.',C('turnip.s1','芜菁','The stew was thick with diced turnip, barley, and carrots.','炖菜里有切丁的芜菁、大麦和胡萝卜，汤汁很浓。','white/purple turnip; turnip root; turnip soup','名词，指以膨大的可食根部为蔬菜的植物。','diced root vegetables are cooked in the stew.','芜菁'),M('The stew contained turnip leaves only, and no edible root vegetable.','The stew contained diced turnip root with barley and carrots.','此处turnip作为蔬菜指可食的膨大根部，不是只指叶子。','meaning'),[Q(1,'A turnip is grown for its…','swollen edible root','bright blue flower','underground train','That is the vegetable sense.','meaning'),Q(1,'What was in the stew?','Turnip, barley, and carrots','Tuna and turmeric only','A screw and a tube','The sentence names the ingredients.','context'),Q(1,'Which phrase is natural?','diced turnip','turniply diced','a diced of turnip','Diced modifies the vegetable.','grammar'),Q(1,'The compound turnip may include a word related to…','Latin napus, meaning turnip','Old English Tiwesdæg','Greek tornos, meaning lathe','The second element is historically linked with napus.','word-formation')]);
P('turnout','Turnout is formed from turn out; it means the number of people attending an event or the number who vote in an election.',[C('turnout.s1','出席人数','There was a large turnout for the school concert despite the snow.','尽管下雪，学校音乐会仍有很多人到场。','a large/low turnout; turnout for an event','名词，指到场参加活动的人数。','many people attend the concert.','出席人数'),C('turnout.s2','投票率','Voter turnout was low because the election took place during a severe storm.','由于选举期间遭遇强风暴，投票率较低。','voter/election turnout; turnout at the polls','名词，指参加投票的选民人数或比例。','few eligible voters cast ballots.','投票率')],M('Voter turnout was low, meaning every eligible voter cast a ballot.','Voter turnout was low, meaning only a small share of eligible voters voted.','low turnout表示参与人数或比例较少。','meaning'),[Q(1,'Turnout at a concert is…','the number of people who attend','the number of performers on stage only','a road junction','Sense 1 is attendance.','meaning'),Q(2,'Low voter turnout means…','few eligible voters took part','all voters cast ballots','a factory made many parts','Sense 2 concerns voting.','context'),Q(1,'Which phrase is natural?','a large turnout for the concert','a turnout concertly large','turnout of large for concert','For introduces the event attended.','grammar'),Q(1,'Turnout is formed from…','the phrasal verb turn out','turnip plus -ed','the Latin word for shame','The noun names people turning out to attend or vote.','word-formation')]);
P('turnover','Turnover is formed from turn over; in business it means money received during a period, and it can also mean the rate at which staff leave or goods are replaced.',[C('turnover.s1','营业额','The shop reported a ten-percent rise in turnover after opening its online store.','这家商店开设网店后报告营业额增长了百分之十。','annual turnover; increase in turnover','名词，指企业在一定时期内的销售收入总额。','the business receives more money from sales.','营业额'),C('turnover.s2','人员/货物流动率','Staff turnover is high because many employees leave within their first year.','员工流动率很高，因为许多人在入职第一年内就离开了。','staff/employee turnover; high turnover','名词，指员工离职补充或商品售出替换的频率。','workers leave and need to be replaced often.','人员流动率')],M('The shop reported higher turnover, meaning it received less money from sales this year.','The shop reported higher turnover, meaning its sales income increased.','营业额上升表示销售收入增加，而不是减少。','meaning'),[Q(1,'Business turnover is…','the money received from sales over a period','the number of roads at a junction','the price of one flower','Sense 1 is sales revenue.','meaning'),Q(2,'High staff turnover means…','many workers leave and are replaced','all workers stay permanently','the company stopped selling goods','Sense 2 is staff movement.','context'),Q(1,'Which phrase is natural?','annual turnover rose','annual turnoverly rose','turnover annual of rose','Annual modifies the reporting period.','grammar'),Q(1,'Turnover is related to the phrasal verb…','turn over','turn off only','tune in','The noun developed from the idea of things changing hands.','word-formation')]);
P('turnpike','Turnpike combines turn and pike, an old word for a spiked barrier; it names a main road where a toll was charged, and in some regions a toll expressway.',C('turnpike.s1','收费公路','We left the turnpike at the next toll plaza and continued on a local road.','我们在下一个收费广场驶离收费公路，转上了地方道路。','toll turnpike; turnpike road; leave the turnpike','名词，指收取通行费的主干道或高速公路。','the drivers pay to use the major road.','收费公路'),M('They left the turnpike without paying, although the road had no toll and no main route.','They left the toll road after passing the toll plaza.','turnpike在该义项指收费主干道，句中承认有收费站。','meaning'),[Q(1,'A turnpike is…','a major road that charges a toll','a small passage through a hill','a flower root','That is the road sense.','meaning'),Q(1,'Where did they leave the turnpike?','At the next toll plaza','At a school audition','Inside an underground train','The context gives the exit point.','context'),Q(1,'Which phrase is natural?','leave the turnpike at a toll plaza','leave at turnpiking toll the','turnpike leave to plaza','At marks the exit location.','grammar'),Q(1,'The pike in the older compound referred to…','a spiked barrier','a plant bulb','a noisy crowd','The road name is linked with barriers used to collect tolls.','word-formation')]);
P('turpitude','Turpitude comes from Latin turpitudo, “shamefulness,” from turpis, “shameful”; it means very immoral behavior or a depraved character.',C('turpitude.s1','卑劣行为','The statute bars entry for crimes involving moral turpitude, such as fraud.','法规禁止犯有涉及道德败坏行为（例如欺诈）的人入境。','moral turpitude; crimes of turpitude','名词，指极不道德的行为或卑劣品格。','fraud is given as a serious moral offense.','卑劣行为'),M('The court described the fraud as moral turpitude, although it was an act of exceptional honesty.','The court described the fraud as moral turpitude, an act of serious dishonesty.','turpitude指卑劣或不道德，与诚实行为相反。','meaning'),[Q(1,'Moral turpitude refers to…','very immoral behavior or character','a small road junction','a type of shell-bearing animal','That is the legal and moral sense.','meaning'),Q(1,'Which crime is used as an example?','Fraud','Tuning a radio','Growing a turnip','The context gives fraud as an example.','context'),Q(1,'Which phrase is standard?','a crime involving moral turpitude','a moral turpitudely crime','a crime of morally turpitude','Moral modifies the noun turpitude.','grammar'),Q(1,'Latin turpis meant…','shameful','turnip','turquoise stone','Turpitude retains the root idea of shame.','word-formation')]);
P('turquoise','Turquoise came through French turquoise, “Turkish,” from the name pierre turquoise, “Turkish stone”; it names an opaque blue-green mineral and the color resembling it.',C('turquoise.s1','绿松石/蓝绿色','She wore a ring set with turquoise and chose a turquoise scarf to match it.','她戴着一枚镶绿松石的戒指，并选了一条蓝绿色围巾与之搭配。','turquoise stone; turquoise jewelry; turquoise blue','名词或形容词，指不透明的蓝绿色矿物或类似的蓝绿色。','the stone and scarf share the characteristic color.','绿松石/蓝绿色'),M('She wore turquoise jewelry, but every stone was opaque scarlet red.','She wore turquoise jewelry set with opaque blue-green stones.','turquoise指蓝绿色矿物，不是猩红色。','meaning'),[Q(1,'Turquoise is…','an opaque blue-green mineral or its color','a yellow powder from a root','a small tower','That is the mineral and color sense.','meaning'),Q(1,'What matched the turquoise ring?','A blue-green scarf','A red turnip','A television set','The context says the scarf was chosen to match.','context'),Q(1,'Which phrase is natural?','a turquoise ring','a turquoising ring','a ring turquoisely of','Turquoise can directly modify the noun.','grammar'),Q(1,'French turquoise meant…','Turkish, as in Turkish stone','a legal offense','a tree trunk','The mineral name reflects a historical trade route through Turkey.','word-formation')]);
P('turret','Turret came through French tourette, a diminutive of tour, “tower,” from Latin turris; it names a small tower projecting from a wall or a rotating armored gun structure.',C('turret.s1','小塔/炮塔','A narrow turret projects from the castle wall, while the ship’s gun turret swings toward the harbour.','城堡墙上凸出一座小塔，而船上的炮塔转向港口。','castle turret; gun turret; turreted tower','名词，指墙上凸出的小塔，也指可转动瞄准的装甲炮座。','one structure is a projecting tower and the other rotates to aim.','小塔/炮塔'),M('The gun turret stayed fixed and could not rotate toward any target.','The gun turret rotated to aim toward the harbour entrance.','炮塔这一义项通常可转动以便瞄准。','meaning'),[Q(1,'A castle turret is…','a small tower projecting from a wall','a root vegetable','a toll plaza','Sense 1 is the architectural structure.','meaning'),Q(1,'What did the ships gun turret do?','It swung to aim toward the harbour','It became a flower','It switched off a railway','The context describes rotation.','context'),Q(1,'Which phrase is natural?','a turret projects from a wall','a turret projects wallly from','a projecting turret of walling','From introduces the surface it projects out of.','grammar'),Q(1,'French tourette was a diminutive of a word for…','tower','a bird','a day of the week','The suffix indicates a small tower.','word-formation')]);
P('turtle','The reptile sense of turtle came through a modification of French tortue or tortre, whose deeper origin is unknown; it names a hard-shelled reptile able to draw in its head and legs. The older bird word turtle-dove has a separate history.',C('turtle.s1','龟','The turtle pulled its head and legs into its shell when the dog approached.','狗靠近时，这只龟把头和四肢缩进壳里。','sea/freshwater turtle; turtle shell','名词，指具有坚硬龟壳、能将头和四肢缩入壳内的爬行动物。','the animal retracts into its protective shell.','龟'),M('The turtle exposed its soft body permanently and had no shell to protect it.','The turtle pulled its body into its hard shell for protection.','turtle的典型特征是有坚硬的保护壳。','meaning'),[Q(1,'A turtle is…','a hard-shelled reptile','a fish without a skeleton','a small tower','That is the animal sense.','meaning'),Q(1,'What did the turtle do when the dog approached?','Pulled its head and legs into its shell','Ran a school audition','Switched off a lamp','The context describes the defensive action.','context'),Q(1,'Which phrase is natural?','a sea turtle','a turtlely sea','a sea of turtlely','Sea identifies a habitat or type.','grammar'),Q(1,'The deeper history of turtle is…','uncertain','certainly from Latin for shame','certainly from Japanese for wave','The word is documented, but the precise derivation is unsettled.','word-formation')]);
P('tusk','Tusk is from Old English tusc, “tooth”; it names a long projecting tooth of an elephant, walrus, or wild boar, and can describe a person’s protruding front tooth.',[C('tusk.s1','长獠牙','The elephant lost a tusk in the trap, and rangers treated the injured animal.','大象在陷阱中失去了一根长牙，护林员为受伤的动物进行了治疗。','elephant/walrus tusk; ivory tusk','名词，指大象、海象或野猪长而突出的牙。','the animal has lost a large projecting tooth.','长獠牙'),C('tusk.s2','突出的门牙','He grinned, showing a chipped tusk that stuck out at the front of his mouth.','他咧嘴一笑，露出一颗崩了角、向前突出的门牙。','a chipped/protruding tusk','名词，非正式地指人突出的前牙。','the person has a prominent front tooth.','突出的门牙')],M('The elephant lost a tusk, which was a flat feather growing from its wing.','The elephant lost a tusk, a long projecting tooth.','tusk是突出的牙，不是羽毛。','meaning'),[Q(1,'An elephant tusk is…','a long projecting tooth','a feather on the wing','a road toll barrier','Sense 1 is the animal tooth.','meaning'),Q(2,'He showed a chipped tusk means he showed…','a protruding front tooth','a damaged tree trunk','a small tower','Sense 2 is the informal human use.','context'),Q(1,'Which phrase is natural?','a walrus tusk','a tuskly walrus','a walrus of tusksly','The animal name modifies the type of tusk.','grammar'),Q(1,'Old English tusc meant…','tooth','harbor','turban','The present word retains the tooth meaning.','word-formation')]);
P('tutelage','Tutelage comes from Latin tutela, “guardianship or protection,” from tueri, “watch over”; it means being taught or guided by someone more experienced.',C('tutelage.s1','指导/监护','Under the tutelage of an experienced editor, the apprentice learned to check every source.','在一位经验丰富的编辑指导下，学徒学会了核查每个来源。','under the tutelage of; receive tutelage','名词，指在更有经验者教导或照管下的状态。','the apprentice receives instruction from a mentor.','指导/监护'),M('Under the tutelage of the editor, the apprentice received no instruction or guidance.','Under the tutelage of the editor, the apprentice received regular guidance.','tutelage表示教导或指导，完全没有指导与之矛盾。','meaning'),[Q(1,'Under an editors tutelage means…','being taught or guided by the editor','being ignored by the editor','working without any instruction','That is the noun meaning.','meaning'),Q(1,'What did the apprentice learn?','To check every source','To grow a turnip','To drive a turnpike','The context states the training goal.','context'),Q(1,'Which phrase is standard?','under the tutelage of a mentor','under a mentor tutelage to','tutelage underly a mentor of','Of introduces the person providing guidance.','grammar'),Q(1,'Latin tutela meant…','guardianship or protection','blue-green stone','a turning point','The word began with the idea of watching over someone.','word-formation')]);
P('tutor','Tutor comes from Latin tutor, “guardian or protector,” from tueri, “watch over”; it names a teacher for one person or a small group and also means teach privately.',[C('tutor.s1','辅导教师','She works as a maths tutor and helps three students prepare for their exams.','她是一名数学辅导教师，帮助三名学生备考。','private/maths tutor; work as a tutor','名词，指一对一或小班授课的教师，也可指负责学生学习的人。','the teacher works with a small group.','辅导教师'),C('tutor.s2','辅导','He tutors children in English at the community centre on weekends.','他周末在社区中心辅导孩子们学习英语。','tutor someone in a subject; tutor privately','动词，指给某人进行私人或小班教学。','the children receive English instruction.','辅导')],M('She works as a maths tutor but never teaches or helps any student.','She works as a maths tutor and helps students prepare for exams.','tutor作为辅导教师，工作内容包括教学和帮助学生。','meaning'),[Q(1,'A maths tutor is…','a teacher who helps one person or a small group','a road toll barrier','a person who pulls a ship','Sense 1 is the teacher.','meaning'),Q(2,'He tutors children in English means he…','teaches them English privately or in a small group','asks them to turn off the television','holds their property in trust','Sense 2 is the verb.','context'),Q(1,'Which pattern is correct?','tutor students in English','tutor English at students','tutor students Englishly in','In introduces the subject taught.','grammar'),Q(1,'Latin tutor referred to a…','guardian or protector','turquoise mineral','tunnel','The teaching sense developed from the idea of guiding or guarding.','word-formation')]);
P('tutorial','Tutorial is formed from tutor plus -ial; it names a small teaching session, step-by-step instructional material, or something relating to teaching or personal coaching.',[C('tutorial.s1','小班辅导课','We have a tutorial every Friday afternoon with six students and one instructor.','我们每周五下午有一节小班辅导课，六名学生由一位老师指导。','weekly/tutorial class; attend a tutorial','名词，指教师为少数学生提供帮助的小班课。','one instructor works with a small group.','小班辅导课'),C('tutorial.s2','教程','Watch this tutorial before installing the software so you can follow each step.','安装软件前先看这个教程，这样就能按步骤操作。','video/online tutorial; step-by-step tutorial','名词，指逐步讲解如何完成某项操作的书面或视频材料。','the video demonstrates the process in sequence.','教程'),C('tutorial.s3','辅导性质的','The students met in a tutorial group to discuss the reading with their instructor.','学生们在辅导小组中与老师讨论阅读材料。','tutorial group/session; tutorial support','形容词，指与教学或个别指导有关的。','the group meets for guided instruction.','辅导性质的')],M('The video tutorial gave no steps or instructions and did not explain how to install the software.','The video tutorial showed each installation step in order.','tutorial作为教程应提供逐步说明，完全没有步骤不符合此处用法。','meaning'),[Q(1,'A Friday tutorial with six students is…','a small teaching session','a television broadcast only','a hard-shelled animal','Sense 1 is the class.','meaning'),Q(2,'A software tutorial helps a viewer…','learn a process step by step','choose a voting station','turn a village into a town','Sense 2 is instructional material.','context'),Q(3,'A tutorial group is…','a group related to guided teaching','a group of road tolls','a group of sea waves','Sense 3 is adjectival.','meaning'),Q(1,'Which phrase is natural?','watch an online tutorial','watch a tutorially onlineing','tutorial watch to an online','Watch takes the tutorial as its object.','grammar')]);
P('TV','TV abbreviates television, formed from Greek tēle, “far,” and Latin visionem, “seeing”; it means the broadcasting system or a device that receives moving pictures and sound.',C('TV.s1','电视/电视机','They watched the final on TV after dinner, using the set in the living room.','晚饭后，他们在客厅用电视机观看了决赛。','watch TV; TV set; live TV','名词，指电视广播媒介或接收电视节目的设备。','the family watches a broadcast on a receiver.','电视'),M('They watched the final on TV, but there was no broadcast or receiving device.','They watched the final on a television set receiving the broadcast.','此处TV指电视广播或接收设备，完全没有广播和设备便无法观看。','meaning'),[Q(1,'TV can mean…','the television broadcast system or its receiving device','a small teaching group','a flower root','That is the source definition.','meaning'),Q(1,'What did they watch on TV?','The final','A court trial','A seaquake','The context names the program.','context'),Q(1,'Which phrase is natural?','watch TV after dinner','watch at TV after dinnerly','watch televisioning after the dinner at','Watch TV is the common phrase.','collocation'),Q(1,'Television combines elements meaning…','far and seeing','turn and pike','swollen and disease','The full word refers to seeing something at a distance.','word-formation')]);
P('twain','Twain comes from Old English twēgen, “two”; it is now mainly literary or archaic and refers to two people or things, as in “never the twain shall meet.”',C('twain.s1','两者','The old proverb says never the twain shall meet, referring to the two rival traditions.','那句古老谚语说“两者永不相遇”，指的是两种相互对立的传统。','never the twain shall meet; the twain','名词，古旧或文学用语，指两个人或两件事。','twain refers to the two traditions.','两者'),M('The phrase never the twain shall meet refers to seven unrelated traditions.','The phrase never the twain shall meet refers to two traditions.','twain是古旧用词，意思是两个，不是七个。','meaning'),[Q(1,'Twain is an old or literary word for…','two people or things','a large crowd','a television set','That is its meaning.','meaning'),Q(1,'In the proverb, what does the twain refer to?','Two rival traditions','Three separate countries','One person only','The example identifies two traditions.','context'),Q(1,'Which expression uses twain naturally?','never the twain shall meet','never the twaining shall meeting','twain to meet neverly','This is the established literary expression.','usage'),Q(1,'Old English twēgen meant…','two','far-seeing','a swollen lump','Twain preserves the historical number meaning.','word-formation')]);
P('tweak','Tweak is probably from a Scots or northern English verb meaning pinch or twist; it now means make a small adjustment to improve something, or pinch and twist lightly.',[C('tweak.s1','微调','We tweaked the audio settings and the background hiss disappeared.','我们微调了音频设置，背景嘶声就消失了。','tweak settings/design; make a small tweak','动词，指对设置或细节作小幅调整以改善效果。','a slight adjustment fixes the noise.','微调'),C('tweak.s1','轻拧/捏','The child tweaked the loose thread gently to pull it from the sweater.','孩子轻轻拧住松线头，把它从毛衣上拉了下来。','tweak a nose; tweak a thread','动词，指轻轻捏住并扭动或拉动。','the fingers pinch and twist the thread.','轻拧/捏')],M('We tweaked the audio settings by making them much worse and leaving the hiss louder.','We tweaked the audio settings slightly until the background hiss disappeared.','tweak在这里表示小幅调整并改善效果，不是恶化设置。','meaning'),[Q(1,'To tweak audio settings is to…','make a small adjustment','replace the entire sound system','turn the set into a television','Sense 1 is a minor adjustment.','meaning'),Q(1,'What happened after the settings were tweaked?','The background hiss disappeared','The screen turned blue','A crowd caused a tumult','The context states the improvement.','context'),Q(1,'Which phrase is natural?','tweak the design slightly','tweak the design into slightly','slightly tweakings the design','Slightly modifies the adjustment.','grammar'),Q(1,'The earlier sense of tweak was probably…','pinch or twist','speak with a tutor','travel on a toll road','The modern adjustment sense developed from a small physical twist.','word-formation')]);
P('tweezers','Tweezers came from tweezes, the plural of an older tweeze, meaning a small case for instruments; tweeze was shortened from etwee, itself from French étui, ‘small case.’ The meaning shifted from the case to the pincer-like tool inside it.',C('tweezers.s1','镊子','She removed the splinter with tweezers because her fingers could not grip it.','她用镊子取出了木刺，因为手指抓不住它。','a pair of tweezers; use tweezers to remove','名词复数，指用于夹取手指难以抓住小物体的镊状工具。','the narrow pincers grip a tiny splinter.','镊子'),M('She removed the splinter with tweezers, a large spoon used for serving soup.','She removed the splinter with tweezers, a small pincer-like tool.','tweezers是夹取小物体的镊状工具，不是汤勺。','meaning'),[Q(1,'Tweezers are…','small pincers for grasping tiny objects','a large tool for stirring soup','a road where tolls are collected','That is the tool definition.','meaning'),Q(1,'Why did she use tweezers?','Her fingers could not grip the splinter','She needed to watch TV','She was tuning a piano','The context explains the need for a precise grip.','context'),Q(1,'Which expression is standard?','a pair of tweezers','a tweezer','two tweezerses','The tool name is normally plural and commonly counted as a pair.','grammar'),Q(1,'The older history of tweeze is…','uncertain, possibly linked with a case of instruments','definitely from Greek for two','from Latin for shamefulness','The origin is not secure, so it is marked cautiously.','word-formation')]);
})(typeof window!=='undefined'?window:globalThis);
